// messages are printed to stderr as `[LEVEL<5> target] message`, with any
// continuation lines indented by 4 extra spaces.

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Level {
    Off,
    Error,
    Warn,
    Info,
    Debug,
    Trace,
}

impl Level {
    pub fn parse(s: &str) -> Option<Level> {
        match s {
            "off" => Some(Level::Off),
            "error" => Some(Level::Error),
            "warn" => Some(Level::Warn),
            "info" => Some(Level::Info),
            "debug" => Some(Level::Debug),
            "trace" => Some(Level::Trace),
            _ => None,
        }
    }
    fn name(self) -> &'static str {
        match self {
            Level::Off => "OFF",
            Level::Error => "ERROR",
            Level::Warn => "WARN",
            Level::Info => "INFO",
            Level::Debug => "DEBUG",
            Level::Trace => "TRACE",
        }
    }
    fn rank(self) -> u8 {
        match self {
            Level::Off => 0,
            Level::Error => 1,
            Level::Warn => 2,
            Level::Info => 3,
            Level::Debug => 4,
            Level::Trace => 5,
        }
    }
}

use std::sync::atomic::{AtomicU8, Ordering};

static LEVEL: AtomicU8 = AtomicU8::new(3);

pub fn set_level(l: Level) {
    LEVEL.store(l.rank(), Ordering::Relaxed);
}

pub fn enabled(level: Level) -> bool {
    level.rank() <= LEVEL.load(Ordering::Relaxed) && LEVEL.load(Ordering::Relaxed) != 0
}

fn indent(msg: &str) -> String {
    let mut out = String::new();
    for (i, line) in msg.split('\n').enumerate() {
        if i > 0 {
            out.push('\n');
            out.push_str("    ");
        }
        out.push_str(line);
    }
    out
}

pub fn log(level: Level, target: &str, msg: &str) {
    if !enabled(level) {
        return;
    }
    let formatted = format!("[{:5} {}] {}", level.name(), target, indent(msg));
    eprintln!("{}", formatted);
}

#[macro_export]
macro_rules! log_error {
    ($target:expr, $($arg:tt)*) => { $crate::log::log($crate::log::Level::Error, $target, &format!($($arg)*)) }
}
EOF
echo done"}

