];

pub fn is_keyword(s: &str) -> bool {
    KEYWORDS.contains(&s)
}

/// Characters that are silently dropped by the identifier conversions.
fn is_dropped(c: char) -> bool {
    matches!(c, ' ' | '-' | '/' | '(' | ')' | '[' | ']')
}

pub fn to_snake_case(n: &str) -> String {
    let mut out = String::new();
    let mut prev: Option<char> = None;
