                            self.i += 1;
                        }
                        _ => {
                            let v = self.parse_value()?;
                            items.push(v);
                        }
                    }
                }
            }
            Some(b'{') => {
                self.i += 1;
                let mut table = Vec::new();
                loop {
                    self.skip_ws_nl();
                    match self.peek() {
                        None => {
                            return Err(self.err("invalid inline table", Some("expected `}`")));
                        }
                        Some(b'}') => {
                            self.i += 1;
                            return Ok(Val::Table(table));
                        }
                        Some(b',') => {
                            self.i += 1;
                        }
                        _ => {
                            let key = self.parse_key()?;
                            self.skip_ws();
                            match self.peek() {
                                Some(b'=') => self.i += 1,
                                _ => {
                                    return Err(self.err("expected `.`, `=`", None));
                                }
                            }
                            let v = self.parse_value()?;
                            // flatten dotted keys
                            insert(&mut table, &key, v);
                        }
                    }
                }
            }
            Some(b't') | Some(b'f') => {
                let word = self.take_word();
                if word == "true" {
                    return Ok(Val::Bool(true));
                }
                if word == "false" {
                    return Ok(Val::Bool(false));
                }
                Err(self.err("expected newline, `#`", None))
            }
            Some(c) if c == b'-' || c == b'+' || c.is_ascii_digit() => {
                let start = self.i;
                if c == b'-' || c == b'+' {
                    self.i += 1;
                }
                let mut is_float = false;
                while let Some(c) = self.peek() {
                    if c.is_ascii_digit() {
                        self.i += 1;
                    } else if c == b'.' || c == b'e' || c == b'E' {
                        is_float = true;
                        self.i += 1;
                    } else if c == b'_' || c == b'-' || c == b'+' {
                        self.i += 1;
                    } else if c == b'x' || c == b'o' || c == b'b' {
                        self.i += 1;
                    } else if c.is_ascii_hexdigit() {
                        self.i += 1;
                    } else {
                        break;
                    }
                }
                let txt = String::from_utf8_lossy(&self.s[start..self.i]).to_string();
                let txt = txt.replace('_', "");
                if is_float {
                    match txt.parse::<f64>() {
                        Ok(v) => Ok(Val::Float(v)),
                        Err(_) => Err(self.err("invalid number", None)),
                    }
                } else {
                    match txt.parse::<i64>() {
                        Ok(v) => Ok(Val::Int(v)),
                        Err(_) => Err(self.err("invalid integer", None)),
                    }
                }
            }
            Some(_) => Err(self.err("invalid string", Some("expected `\"`, `'`"))),
        }
    }
    fn take_word(&mut self) -> String {
        let start = self.i;
        while let Some(c) = self.peek() {
            if c.is_ascii_alphanumeric() || c == b'_' || c == b'-' {
                self.i += 1;
            } else {
                break;
            }
        }
        String::from_utf8_lossy(&self.s[start..self.i]).to_string()
    }
}

fn insert(table: &mut Vec<(String, Val)>, key: &[String], val: Val) {
    if key.len() == 1 {
        if let Some(pos) = table.iter().position(|(k, _)| *k == key[0]) {
            table[pos].1 = val;
        } else {
            table.push((key[0].clone(), val));
        }
        return;
    }
    let first = key[0].clone();
    if let Some(pos) = table.iter().position(|(k, _)| *k == first) {
        if let Val::Table(t) = &mut table[pos].1 {
            insert(t, &key[1..], val);
        }
    } else {
        let mut t = Vec::new();
        insert(&mut t, &key[1..], val);
        table.push((first, Val::Table(t)));
    }
}

pub fn parse(content: &str) -> Result<Vec<(String, Val)>, TomlError> {
    let mut p = Parser::new(content);
    let mut root: Vec<(String, Val)> = Vec::new();
    let mut current: Vec<String> = Vec::new();
    loop {
        p.skip_ws_nl();
        if p.i >= p.s.len() {
            break;
        }
        if p.peek() == Some(b'[') {
            p.i += 1;
            if p.peek() == Some(b'[') {
                p.i += 1;
                p.skip_ws();
                let key = p.parse_key()?;
                p.skip_ws();
                if p.peek() != Some(b']') {
                    return Err(p.err("expected `]`", None));
                }
                p.i += 1;
                if p.peek() != Some(b']') {
                    return Err(p.err("expected `]`", None));
                }
                p.i += 1;
                // array of tables: ignore (treated as table)
                let mut t = Vec::new();
                insert(&mut root, &key, Val::Table(std::mem::take(&mut t)));
                current = key;
                continue;
            }
            p.skip_ws();
            let key = p.parse_key()?;
            p.skip_ws();
            if p.peek() != Some(b']') {
                return Err(p.err("invalid table header", None));
            }
            p.i += 1;
            insert(&mut root, &key, Val::Table(Vec::new()));
            current = key;
            continue;
        }
        let key = p.parse_key()?;
        p.skip_ws();
        match p.peek() {
            Some(b'=') => {
                p.i += 1;
            }
            None => break,
            _ => return Err(p.err("expected `.`, `=`", None)),
        }
        let val = p.parse_value()?;
        let mut full = current.clone();
        full.extend(key.iter().cloned());
        insert(&mut root, &full, val);
        // consume rest of line
        p.skip_ws();
        match p.peek() {
            Some(b'#') => {
                while let Some(c) = p.peek() {
                    if c == b'\n' {
                        break;
                    }
                    p.i += 1;
                }
            }
            Some(b'\n') => p.i += 1,
            Some(b'\r') => p.i += 1,
            None => break,
            _ => return Err(p.err("expected newline, `#`", None)),
        }
    }
    Ok(root)
}
