// Minimal TOML parser (subset) used for the `-c/--config` file.

#[derive(Debug, Clone)]
pub enum Val {
    Str(String),
    Int(i64),
    Float(f64),
    Bool(bool),
    Array(Vec<Val>),
    Table(Vec<(String, Val)>),
}

impl Val {
    pub fn type_name(&self) -> &'static str {
        match self {
            Val::Str(_) => "string",
            Val::Int(_) => "integer",
            Val::Float(_) => "floating point",
            Val::Bool(_) => "bool",
            Val::Array(_) => "sequence",
            Val::Table(_) => "map",
        }
    }
    pub fn debug_val(&self) -> String {
        match self {
            Val::Str(s) => format!("string {:?}", s),
            Val::Int(i) => format!("integer `{}`", i),
            Val::Float(f) => format!("floating point `{}`", crate::util::fmt_float(*f)),
            Val::Bool(b) => format!("boolean `{}`", b),
            Val::Array(_) => "sequence".to_string(),
            Val::Table(_) => "map".to_string(),
        }
    }
}

pub struct TomlError {
    pub line: usize,
    pub col: usize,
    pub msg: String,
    pub expected: Option<String>,
}

impl TomlError {
    pub fn text(&self, content: &str) -> String {
        let lines: Vec<&str> = content.split('\n').collect();
        let line = lines.get(self.line.saturating_sub(1)).copied().unwrap_or("");
        let num = self.line.to_string();
        let width = num.len().max(1);
        let pad = " ".repeat(width + 1);
        let mut out = format!(
            "TOML parse error at line {}, column {}\n",
            self.line, self.col
        );
        out.push_str(&format!("{}|\n", pad));
        out.push_str(&format!("{:>width$} | {}\n", num, line, width = width));
        out.push_str(&format!("{}|{}^\n", pad, " ".repeat(self.col.saturating_sub(1))));
        out.push_str(&format!("   {}\n", self.msg));
        if let Some(e) = &self.expected {
            out.push_str(&format!("   {}\n", e));
        }
        out.push_str("   ");
        out
    }
}

struct Parser<'a> {
    s: &'a [u8],
    i: usize,
    line: usize,
    line_start: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Parser {
            s: s.as_bytes(),
            i: 0,
            line: 1,
            line_start: 0,
        }
    }
    fn pos(&self) -> (usize, usize) {
        let mut line = 1;
        let mut col = 1;
        for k in 0..self.i {
            if self.s[k] == b'\n' {
                line += 1;
                col = 1;
            } else {
                col += 1;
            }
        }
        (line, col)
    }
    fn err(&self, msg: &str, expected: Option<&str>) -> TomlError {
        let (line, col) = self.pos();
        TomlError {
            line,
            col,
            msg: msg.to_string(),
            expected: expected.map(|s| s.to_string()),
        }
    }
    fn peek(&self) -> Option<u8> {
        self.s.get(self.i).copied()
    }
    fn skip_ws(&mut self) {
        while let Some(c) = self.peek() {
            if c == b' ' || c == b'\t' {
                self.i += 1;
            } else {
                break;
            }
        }
    }
    fn skip_ws_nl(&mut self) {
        loop {
            match self.peek() {
                Some(b' ') | Some(b'\t') | Some(b'\n') | Some(b'\r') => self.i += 1,
                Some(b'#') => {
                    while let Some(c) = self.peek() {
                        if c == b'\n' {
                            break;
                        }
                        self.i += 1;
                    }
                }
                _ => break,
            }
        }
    }
    fn parse_key(&mut self) -> Result<Vec<String>, TomlError> {
        let mut parts = Vec::new();
        loop {
            self.skip_ws();
            let start = self.i;
            let c = match self.peek() {
                Some(c) => c,
                None => return Err(self.err("invalid key", None)),
            };
            let name = if c == b'"' || c == b'\'' {
                self.parse_string(c)?
            } else {
                let mut s = String::new();
                while let Some(c) = self.peek() {
                    if c.is_ascii_alphanumeric() || c == b'_' || c == b'-' {
                        s.push(c as char);
                        self.i += 1;
                    } else {
                        break;
                    }
                }
                if s.is_empty() {
                    return Err(self.err("invalid key", None));
                }
                s
            };
            parts.push(name);
            let _ = start;
            self.skip_ws();
            match self.peek() {
                Some(b'.') => {
                    self.i += 1;
                }
                _ => return Ok(parts),
            }
        }
    }
    fn parse_string(&mut self, quote: u8) -> Result<String, TomlError> {
        // multi-line?
        if quote == b'"' && self.s.get(self.i + 1) == Some(&b'"') && self.s.get(self.i + 2) == Some(&b'"') {
            self.i += 3;
            let mut out = String::new();
            loop {
                if self.i >= self.s.len() {
                    return Err(self.err("invalid multiline basic string", Some("expected `\"\"\"`")));
                }
                if self.s[self.i] == b'"'
                    && self.s.get(self.i + 1) == Some(&b'"')
                    && self.s.get(self.i + 2) == Some(&b'"')
                {
                    self.i += 3;
                    return Ok(out);
                }
                if self.s[self.i] == b'\\' {
                    self.i += 1;
                    if let Some(c) = self.peek() {
                        self.i += 1;
                        match c {
                            b'n' => out.push('\n'),
                            b't' => out.push('\t'),
                            b'r' => out.push('\r'),
                            b'"' => out.push('"'),
                            b'\\' => out.push('\\'),
                            b'\n' => {}
                            c => out.push(c as char),
                        }
                        continue;
                    }
                    continue;
                }
                out.push(self.s[self.i] as char);
                self.i += 1;
            }
        }
        self.i += 1;
        let mut out = String::new();
        loop {
            match self.peek() {
                None => {
                    let e = format!("expected `{}`", quote as char);
                    return Err(self.err("invalid basic string", Some(&e)));
                }
                Some(c) if c == quote => {
                    self.i += 1;
                    return Ok(out);
                }
                Some(b'\n') => {
                    let e = format!("expected `{}`", quote as char);
                    return Err(self.err("invalid basic string", Some(&e)));
                }
                Some(b'\\') => {
                    self.i += 1;
                    let c = match self.peek() {
                        Some(c) => c,
                        None => {
                            let e = format!("expected `{}`", quote as char);
                            return Err(self.err("invalid basic string", Some(&e)));
                        }
                    };
                    self.i += 1;
                    match c {
                        b'n' => out.push('\n'),
                        b't' => out.push('\t'),
                        b'r' => out.push('\r'),
                        b'"' => out.push('"'),
                        b'\\' => out.push('\\'),
                        b'u' => {
                            let mut hex = String::new();
                            for _ in 0..4 {
                                if let Some(c) = self.peek() {
