    }
    fn parse_value(&mut self) -> Result<Val, TomlError> {
        self.skip_ws();
        match self.peek() {
            None => Err(self.err("invalid string", Some("expected `\"`, `'`"))),
            Some(b'"') | Some(b'\'') => {
                let q = self.peek().unwrap();
                Ok(Val::Str(self.parse_string(q)?))
