                self.i += 1;
                let mut items = Vec::new();
                loop {
                    self.skip_ws_nl();
                    match self.peek() {
                        None => {
                            return Err(self.err("invalid array", Some("expected `]`")));
                        }
                        Some(b']') => {
                            self.i += 1;
                            return Ok(Val::Array(items));
                        }
                        Some(b',') => {
                            self.i += 1;
                        }
                        _ => {
                            let v = self.parse_value()?;
                            items.push(v);
                        }
                    }
                }
            }
