// Minimal XML parser with position tracking, mimicking the errors of the
// `xmlparser` crate used by the SVD parser.

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Pos {
    pub line: usize,
    pub col: usize,
}

impl Pos {
    pub fn to_string(&self) -> String {
        format!("{}:{}", self.line, self.col)
    }
}

#[derive(Debug)]
pub struct Element {
    pub name: String,
    pub pos: Pos,
    pub text: String,
    pub children: Vec<Element>,
    pub attrs: Vec<(String, String)>,
}

impl Element {
    pub fn child(&self, name: &str) -> Option<&Element> {
        self.children.iter().find(|c| c.name == name)
    }
    pub fn children_of(&self, name: &str) -> Vec<&Element> {
        self.children.iter().filter(|c| c.name == name).collect()
    }
    pub fn child_text(&self, name: &str) -> Option<String> {
        self.child(name).map(|c| c.text.clone())
    }
    pub fn text_of(&self, name: &str) -> String {
        self.child_text(name).unwrap_or_default()
    }
    pub fn name_value(&self) -> String {
        self.text_of("name")
    }
}

pub struct XmlError {
    pub msg: String,
}

fn err(msg: String) -> XmlError {
    XmlError { msg }
}

pub fn parse(input: &str) -> Result<Element, XmlError> {
    let b: Vec<char> = input.chars().collect();
    let mut p = P { b, i: 0 };
    p.skip_bom();
    p.ws();
    // optional xml declaration / prologue
    while p.i < p.b.len() {
        if p.starts_with("<!--") {
            p.comment()?;
            p.ws();
            continue;
        }
        if p.starts_with("<?") {
            p.processing()?;
            p.ws();
            continue;
        }
        break;
    }
    p.ws();
    if p.i >= p.b.len() {
        return Err(err("unknown token at 1:1".to_string()));
    }
    let root = p.element()?;
