fn err(msg: String) -> XmlError {
    XmlError { msg }
}

pub fn parse(input: &str) -> Result<Element, XmlError> {
    let b: Vec<char> = input.chars().collect();
    let mut p = P { b, i: 0 };
    p.skip_bom();
    p.ws();
    // optional xml declaration / prologue
    while p.i < p.b.len() {
        if p.starts_with("<!--") {
            p.comment()?;
            p.ws();
            continue;
        }
        if p.starts_with("<?") {
            p.processing()?;
            p.ws();
            continue;
        }
        break;
    }
    p.ws();
    if p.i >= p.b.len() {
        return Err(err("unknown token at 1:1".to_string()));
    }
    let root = p.element()?;
    p.ws();
    if p.i < p.b.len() {
        // Trailing content: report the position of the offending token.
        let pos = p.pos();
        return Err(err(format!("unknown token at {}", pos.to_string())));
    }
    Ok(root)
}

struct P {
    b: Vec<char>,
    i: usize,
}

impl P {
    fn starts_with(&self, s: &str) -> bool {
        let sc: Vec<char> = s.chars().collect();
        self.b[self.i..].starts_with(&sc)
    }
    fn pos(&self) -> Pos {
        let mut line = 1;
        let mut col = 1;
        for k in 0..self.i {
            if self.b[k] == '\n' {
                line += 1;
                col = 1;
            } else {
                col += 1;
            }
        }
        Pos { line, col }
    }
    fn skip_bom(&mut self) {
        if self.b.len() >= 3 && self.b[0] == '\u{feff}' {
            self.i += 1;
        }
    }
    fn ws(&mut self) {
        while self.i < self.b.len() && (self.b[self.i] == ' ' || self.b[self.i] == '\t' || self.b[self.i] == '\n' || self.b[self.i] == '\r') {
            self.i += 1;
        }
    }
    fn ws_in_element(&mut self) {
        self.ws();
    }
    fn comment(&mut self) -> Result<(), XmlError> {
        self.i += 4;
        loop {
            if self.i >= self.b.len() {
                let pos = self.pos();
                return Err(err(format!("expected '-->' at {}", pos.to_string())));
            }
            if self.starts_with("-->") {
                self.i += 3;
                return Ok(());
            }
            self.i += 1;
        }
    }
    fn processing(&mut self) -> Result<(), XmlError> {
        self.i += 2;
        loop {
            if self.i >= self.b.len() {
                let pos = self.pos();
                return Err(err(format!("expected '?>' at {}", pos.to_string())));
            }
            if self.starts_with("?>") {
                self.i += 2;
                return Ok(());
            }
            self.i += 1;
        }
    }
    fn cdata(&mut self) -> Result<String, XmlError> {
        self.i += 9;
        let start = self.i;
        loop {
            if self.i >= self.b.len() {
                let pos = self.pos();
                return Err(err(format!("expected ']]>' at {}", pos.to_string())));
            }
            if self.starts_with("]]>") {
                let s: String = self.b[start..self.i].iter().collect();
                self.i += 3;
                return Ok(s);
            }
            self.i += 1;
        }
    }
    /// Read text until the next `<`, resolving entity references.
    fn text(&mut self) -> Result<String, XmlError> {
        let mut out = String::new();
        while self.i < self.b.len() && self.b[self.i] != '<' {
            let c = self.b[self.i];
            if c == '&' {
                let amp_pos = self.pos();
                self.i += 1;
                if self.i < self.b.len() && self.b[self.i] == '#' {
                    self.i += 1;
                    let mut n = String::new();
                    while self.i < self.b.len() && self.b[self.i] != ';' {
                        n.push(self.b[self.i]);
                        self.i += 1;
                    }
                    if self.i < self.b.len() {
                        self.i += 1;
                    }
                    let v = if n.starts_with('x') || n.starts_with('X') {
                        u32::from_str_radix(&n[1..], 16).ok()
                    } else {
                        n.parse::<u32>().ok()
                    };
                    match v.and_then(char::from_u32) {
                        Some(ch) => out.push(ch),
                        None => {
                            return Err(err(format!(
                                "unknown entity reference '{}' at {}",
                                n,
                                amp_pos.to_string()
                            )))
                        }
                    }
                    continue;
                }
                let name_pos = self.pos();
                let mut name = String::new();
                while self.i < self.b.len() && self.b[self.i].is_ascii_alphanumeric() {
                    name.push(self.b[self.i]);
                    self.i += 1;
                }
                if self.i < self.b.len() && self.b[self.i] == ';' {
                    self.i += 1;
                } else {
                    return Err(err(format!(
                        "malformed entity reference at {}",
                        name_pos.to_string()
                    )));
                }
                match name.as_str() {
                    "lt" => out.push('<'),
                    "gt" => out.push('>'),
                    "amp" => out.push('&'),
                    "quot" => out.push('"'),
                    "apos" => out.push('\''),
                    _ => {
                        return Err(err(format!(
                            "unknown entity reference '{}' at {}",
                            name,
                            name_pos.to_string()
                        )))
                    }
                }
                continue;
            }
            out.push(c);
            self.i += 1;
        }
        Ok(out)
    }
    fn ident(&mut self) -> String {
        let start = self.i;
        while self.i < self.b.len()
            && (self.b[self.i].is_ascii_alphanumeric()
                || self.b[self.i] == '_'
                || self.b[self.i] == ':'
                || self.b[self.i] == '-'
                || self.b[self.i] == '.')
        {
            self.i += 1;
        }
        self.b[start..self.i].iter().collect()
    }
    fn element(&mut self) -> Result<Element, XmlError> {
        let pos = self.pos();
        if self.b[self.i] != '<' {
            return Err(err(format!("unknown token at {}", pos.to_string())));
        }
        self.i += 1;
        let name = self.ident();
        if name.is_empty() {
            return Err(err(format!("unknown token at {}", pos.to_string())));
        }
        let mut attrs = Vec::new();
        loop {
            self.ws_in_element();
            if self.i >= self.b.len() {
                return Err(err(format!(
                    "expected '>' at {}",
                    self.pos().to_string()
                )));
            }
            let c = self.b[self.i];
            if c == '>' {
                self.i += 1;
                break;
            }
            if c == '/' {
                if self.b.get(self.i + 1) == Some(&'>') {
                    self.i += 2;
                    return Ok(Element {
                        name,
                        pos,
                        text: String::new(),
                        children: Vec::new(),
                        attrs,
                    });
                }
                let p2 = self.pos();
                return Err(err(format!("expected '>' not '/' at {}", p2.to_string())));
            }
            // attribute
            let aname = self.ident();
            if aname.is_empty() {
                let p2 = self.pos();
                return Err(err(format!(
                    "expected an attribute name at {}",
                    p2.to_string()
                )));
            }
            self.ws_in_element();
            match self.b[self.i] {
                '=' => {
                    self.i += 1;
                }
                _ => {
                    let p2 = self.pos();
                    return Err(err(format!("expected '=' not '{}' at {}", c, p2.to_string())));
                }
            }
            self.ws_in_element();
            let q = self.b[self.i];
            if q != '"' && q != '\'' {
                let p2 = self.pos();
                return Err(err(format!("expected a quote not '{}' at {}", q, p2.to_string())));
            }
            self.i += 1;
            let mut aval = String::new();
            loop {
                if self.i >= self.b.len() {
                    let p2 = self.pos();
                    return Err(err(format!(
                        "expected '{}' not '{}' at {}",
                        q,
                        '<',
                        p2.to_string()
                    )));
                }
                let c = self.b[self.i];
                if c == q {
                    self.i += 1;
                    break;
                }
                if c == '<' {
                    let p2 = self.pos();
                    return Err(err(format!("expected '{}' not '<' at {}", q, p2.to_string())));
                }
                if c == '&' {
                    // entities in attribute values
                    let save = self.i;
                    self.i += 1;
                    let mut name = String::new();
                    while self.i < self.b.len() && self.b[self.i].is_ascii_alphanumeric() {
                        name.push(self.b[self.i]);
                        self.i += 1;
                    }
                    if self.i < self.b.len() && self.b[self.i] == ';' {
                        self.i += 1;
                        match name.as_str() {
                            "lt" => aval.push('<'),
                            "gt" => aval.push('>'),
                            "amp" => aval.push('&'),
                            "quot" => aval.push('"'),
                            "apos" => aval.push('\''),
                            _ => {
                                let p2 = self.pos();
                                return Err(err(format!(
                                    "unknown entity reference '{}' at {}",
                                    name,
                                    p2.to_string()
                                )));
                            }
                        }
                        continue;
                    }
                    self.i = save;
                }
                aval.push(c);
                self.i += 1;
            }
            attrs.push((aname, aval));
        }
        // read content
        let mut text = String::new();
        let mut children = Vec::new();
        loop {
            if self.i >= self.b.len() {
                let p2 = self.pos();
                return Err(err(format!("expected '{}' at {}", name, p2.to_string())));
            }
            if self.starts_with("</") {
                self.i += 2;
                let cname = self.ident();
                self.ws_in_element();
                if self.i >= self.b.len() || self.b[self.i] != '>' {
                    let p2 = self.pos();
                    return Err(err(format!("expected '>' at {}", p2.to_string())));
                }
                self.i += 1;
                if cname != name {
                    return Err(err(format!(
                        "expected '{}' tag, not '{}' at {}",
                        name,
                        cname,
                        self.pos().to_string()
                    )));
                }
                break;
            }
            if self.starts_with("<!--") {
                self.comment()?;
                continue;
            }
            if self.starts_with("<?") {
                self.processing()?;
                continue;
            }
            if self.starts_with("<") {
                let child = self.element()?;
                children.push(child);
                continue;
            }
            let t = self.text()?;
            text.push_str(&t);
        }
        Ok(Element {
            name,
            pos,
            text,
            children,
            attrs,
        })
    }
}
