impl Device {
    /// Deduplicated list of all interrupts of the device.
    pub fn interrupt_list(&self) -> Vec<Interrupt> {
        let mut out: Vec<Interrupt> = Vec::new();
        for p in &self.peripherals {
            for i in &p.interrupts {
                if !out.iter().any(|x| {
                    x.name == i.name && x.description == i.description && x.value == i.value
                }) {
                    out.push(i.clone());
                }
            }
        }
        out
    }
