// ---------------------------------------------------------------------------
// Bit range parsing
// ---------------------------------------------------------------------------

pub enum BitRangeError {
    Syntax,
    ParseError,
    Size,
    WidthZero,
}

impl BitRangeError {
    pub fn text(&self) -> String {
        match self {
            BitRangeError::Syntax => "Bit range invalid, Syntax".to_string(),
            BitRangeError::ParseError => "Bit range invalid, ParseError".to_string(),
            BitRangeError::Size => "Bit range invalid, Size".to_string(),
            BitRangeError::WidthZero => {
                "`BitRange error: bitRange width of 0 does not make sense".to_string()
            }
        }
    }
}

pub fn parse_bit_range(s: &str) -> Result<(u32, u32), BitRangeError> {
    let t = s.trim();
    if t.is_empty() || !t.starts_with('[') || !t.ends_with(']') {
        return Err(BitRangeError::ParseError);
    }
    let inner = &t[1..t.len() - 1];
    let parts: Vec<&str> = inner.split(':').collect();
    if parts.len() != 2 {
        return Err(BitRangeError::ParseError);
    }
    let msb = parts[0].trim();
    let lsb = parts[1].trim();
    if msb.is_empty() || lsb.is_empty() {
        return Err(BitRangeError::ParseError);
    }
    let m: u32 = match msb.parse() {
        Ok(v) => v,
        Err(_) => return Err(BitRangeError::ParseError),
    };
    let l: u32 = match lsb.parse() {
        Ok(v) => v,
        Err(_) => return Err(BitRangeError::ParseError),
    };
    if m < l {
        return Err(BitRangeError::Size);
    }
    let width = m - l + 1;
    if width == 0 {
        return Err(BitRangeError::WidthZero);
    }
    Ok((l, width))
}

pub fn bit_range_from_offset_width(off: u32, width: u32) -> Result<(u32, u32), BitRangeError> {
    if width == 0 {
        return Err(BitRangeError::WidthZero);
    }
    Ok((off, width))
}

// ---------------------------------------------------------------------------
// Element helpers
// ---------------------------------------------------------------------------

fn get_name(el: &Element) -> Result<String, E> {
    match el.child("name") {
        Some(n) => Ok(n.text.clone()),
        None => Err(E::new(missing_tag("name"))),
    }
}

fn get_desc(el: &Element) -> Option<String> {
    el.child_text("description").map(|s| {
        // normalise newlines in descriptions
        s
    })
}

fn parse_dim(el: &Element, tag: &str) -> Result<Option<Dim>, E> {
    let dim_el = match el.child("dim") {
        Some(d) => d,
        None => return Ok(None),
    };
    let dim = parse_int10(&dim_el.text, dim_el, "dim")?;
    let inc_el = match el.child("dimIncrement") {
        Some(d) => d,
        None => {
            return Err(E::new(missing_tag("dimIncrement"))
                .with(parsing(tag, &el.name_value(), &el.pos)))
        }
    };
    let increment = parse_int(&inc_el.text, inc_el, "dimIncrement")?;
    let index = match el.child("dimIndex") {
        Some(d) => {
            let t = d.text.trim();
            if t.contains('-') && !t.contains(',') {
                // range form
                let parts: Vec<&str> = t.split('-').collect();
                if parts.len() != 2 {
                    return Err(E::new(format!(
                        "dimIndex tag is not a valid range: `{}`",
                        t
                    ))
                    .with(in_tag(tag, &el.name_value())));
                }
                let start = parse_int(parts[0].trim(), d, "dimIndex")?;
                let end = parse_int(parts[1].trim(), d, "dimIndex")?;
                Some(
                    (start..=end)
                        .map(|i| i.to_string())
                        .collect::<Vec<String>>(),
                )
            } else {
                Some(t.split(',').map(|s| s.to_string()).collect::<Vec<String>>())
            }
        }
        None => None,
    };
    Ok(Some(Dim { dim, increment, index }))
}

fn check_dim_index(dim: &Dim, tag: &str, name: &str, el: &Element) -> Result<(), E> {
    if let Some(idx) = &dim.index {
        if idx.len() as u64 != dim.dim {
            return Err(E::new(format!(
                "dimIndex tag must contain {} indexes, found {}",
                dim.dim,
                idx.len()
            ))
            .with(parsing(tag, name, &el.pos)));
        }
    }
    Ok(())
}

/// Returns the name with `%s` removed and a flag whether it contained `%s`.
pub fn strip_percent(name: &str) -> String {
    name.replace("%s", "")
}

fn require_percent(name: &str, tag: &str, el: &Element) -> Result<(), E> {
    if !name.contains("%s") {
        return Err(E::new(format!(
            "Name `{}` in tag `{}` is missing a %s placeholder",
            name, tag
        ))
        .with(parsing(tag, name, &el.pos)));
    }
    Ok(())
}

// ---------------------------------------------------------------------------
// Parsing
// ---------------------------------------------------------------------------

pub fn parse(input: &str) -> Result<Device, E> {
    let root = match crate::xml::parse(input) {
        Ok(r) => r,
        Err(e) => return Err(E::new(e.msg)),
    };
    let root = {
        if root.name != "device" {
            return Err(E::new(format!(
                "expected 'device' tag, not '{}' at {}",
                root.name,
                root.pos.to_string()
            )));
        }
        root
    };
    let name = match get_name(&root) {
        Ok(n) => n,
        Err(e) => return Err(e.with(parse_unknown("device", &root.pos))),
    };
    let device_ctx = |r: Result<Device, E>| -> Result<Device, E> {
        r.map_err(|e| e.with(parsing("device", &name, &root.pos)))
    };
    device_ctx(parse_device_el(&root, name))
}

fn parse_device_el(root: &Element, name: String) -> Result<Device, E> {
    let dev_ctx = |r: Result<Device, E>| -> Result<Device, E> {
        r.map_err(|e| e.with(parsing("device", &name, &root.pos)))
    };
    let desc = get_desc(&root);
    let size = match root.child("size") {
        Some(s) => parse_int(&s.text, s, "size")? as u32,
        None => 32,
    };
    let access = match root.child("access") {
        Some(a) => Some(ctx_res(Access::parse(&a.text, a))?),
        None => None,
    };
    let reset_value = match root.child("resetValue") {
        Some(r) => Some(parse_int(&r.text, r, "resetValue")?),
        None => None,
    };
    if let Some(cpu) = root.child("cpu") {
        let _ = parse_cpu(cpu, &name, &root.pos)?;
    }
    let peripherals_el = match root.child("peripherals") {
        Some(p) => p,
        None => return Err(E::new(missing_tag("peripherals"))),
    };
    let mut peripherals = Vec::new();
    for pel in peripherals_el.children_of("peripheral") {
        let p = ctx_res(parse_peripheral(pel, size, access, reset_value))?
            .with(in_tag("device", &name))?;
        peripherals.push(p);
    }
    let device = Device {
        name,
        description: desc,
        size,
        access,
        reset_value,
        peripherals,
        interrupts: Vec::new(),
    };
    Ok(device)
}

fn ctx_res<T>(r: Result<T, E>) -> Result<T, E> {
    r
}

fn parse_cpu(el: &Element, dev_name: &str, _root_pos: &Pos) -> Result<(), E> {
    let name = match get_name(el) {
        Ok(n) => n,
        Err(e) => return Err(e.with(parse_unknown("cpu", &el.pos))),
    };
    let _ = name;
    // required children
    for tag in ["endian", "mpuPresent", "fpuPresent", "nvicPrioBits", "hasVendorSpecificCells", "sramSize"] {
        match el.child(tag) {
            Some(c) => {
                if tag == "nvicPrioBits" {
                    let _ = parse_int10(&c.text, c, tag)?;
                } else if tag == "sramSize" {
                    let _ = parse_int(&c.text, c, tag)?;
                }
            }
            None => return Err(E::new(missing_tag(tag)).with(parsing("cpu", &name, &el.pos))),
        }
    }
    Ok(())
}

fn parse_interrupt(el: &Element, size: u32, access: Option<Access>, reset_value: Option<u64>) -> Result<Interrupt, E> {
    let name = match get_name(el) {
        Ok(n) => n,
        Err(e) => return Err(e.with(parse_unknown("interrupt", &el.pos))),
    };
    let _ = (size, access, reset_value);
    let ctx = |r: Result<Interrupt, E>| r.map_err(|e| e.with(parsing("interrupt", &name, &el.pos)));
    ctx(async {
        let value_el = el
            .child("value")
            .ok_or_else(|| E::new(missing_tag("value")))?;
        let value = parse_int10(&value_el.text, value_el, "value")?;
        Ok(Interrupt {
            name,
            description: get_desc(el),
            value,
        })
    })
}

fn parse_peripheral(
    el: &Element,
    dev_size: u32,
    dev_access: Option<Access>,
    dev_reset: Option<u64>,
) -> Result<Peripheral, E> {
    let name = match get_name(el) {
        Ok(n) => n,
        Err(e) => return Err(e.with(parse_unknown("peripheral", &el.pos))),
    };
    let peri_ctx = |r: Result<Peripheral, E>| -> Result<Peripheral, E> {
        r.map_err(|e| e.with(parsing("peripheral", &name, &el.pos)))
    };
    peri_ctx(async {
        let dim = parse_dim(el, "peripheral")?;
        if dim.is_some() {
            require_percent(&name, "peripheral", el)?;
        }
        if let Some(d) = &dim {
            check_dim_index(d, "peripheral", &name, el)?;
        }
        let base_el = el
            .child("baseAddress")
            .ok_or_else(|| E::new(missing_tag("baseAddress")))?;
        let base_address = parse_int(&base_el.text, base_el, "baseAddress")?;
        let size = match el.child("size") {
            Some(s) => parse_int(&s.text, s, "size")? as u32,
            None => dev_size,
        };
        let access = match el.child("access") {
            Some(a) => Some(Access::parse(&a.text, a)?),
            None => dev_access,
        };
        let reset_value = match el.child("resetValue") {
            Some(r) => Some(parse_int(&r.text, r, "resetValue")?),
            None => dev_reset,
        };
        let mut interrupts = Vec::new();
        for i in el.children_of("interrupt") {
            interrupts.push(parse_interrupt(i, size, access, reset_value)?);
        }
        let mut children = Vec::new();
        if let Some(regs) = el.child("registers") {
            for r in &regs.children {
                match r.name.as_str() {
                    "register" => children.push(RegOrCluster::Reg(parse_register(r, size, access, reset_value)?)),
                    "cluster" => children.push(RegOrCluster::Cluster(parse_cluster(r, size, access, reset_value)?)),
                    _ => {}
                }
            }
        }
        Ok(Peripheral {
            name,
            description: get_desc(el),
            base_address,
            group_name: el.child_text("groupName"),
            dim,
            interrupts,
            children,
            derive_from: el.child_text("derivedFrom"),
            size: Some(size),
            access,
            reset_value,
        })
    })
}

fn parse_register(
    el: &Element,
    peri_size: u32,
    peri_access: Option<Access>,
    peri_reset: Option<u64>,
) -> Result<Register, E> {
    let name = match get_name(el) {
        Ok(n) => n,
        Err(e) => return Err(e.with(parse_unknown("register", &el.pos))),
    };
    let reg_ctx = |r: Result<Register, E>| -> Result<Register, E> {
        r.map_err(|e| e.with(parsing("register", &name, &el.pos)))
    };
    let inner = move || -> Result<Register, E> {
        let dim = parse_dim(el, "register")?;
        if dim.is_some() {
            require_percent(&name, "register", el)?;
        }
        if let Some(d) = &dim {
            check_dim_index(d, "register", &name, el)?;
        }
        let off_el = el
            .child("addressOffset")
            .ok_or_else(|| E::new(missing_tag("addressOffset")))?;
        let offset = parse_int(&off_el.text, off_el, "addressOffset")?;
        let size = match el.child("size") {
            Some(s) => parse_int(&s.text, s, "size")? as u32,
            None => peri_size,
        };
        let access = match el.child("access") {
            Some(a) => Some(Access::parse(&a.text, a)?),
            None => peri_access,
        };
        let reset_value = match el.child("resetValue") {
            Some(r) => Some(parse_int(&r.text, r, "resetValue")?),
            None => peri_reset,
        };
        let reset_mask = match el.child("resetMask") {
            Some(r) => Some(parse_int(&r.text, r, "resetMask")?),
            None => None,
        };
        let mut fields = Vec::new();
        if let Some(flds) = el.child("fields") {
            for f in flds.children_of("field") {
                fields.push(parse_field(f)?);
            }
        }
        Ok(Register {
            name,
            description: get_desc(el),
            offset,
            size: Some(size),
            access,
            reset_value,
            reset_mask,
            fields,
            alternate_register: el.child_text("alternateRegister"),
            alternate_group: el.child_text("alternateGroup"),
            dim,
            derive_from: el.child_text("derivedFrom"),
        })
    };
    reg_ctx(inner())
}

fn parse_field(el: &Element) -> Result<Field, E> {
    let name = match get_name(el) {
        Ok(n) => n,
        Err(e) => return Err(e.with(parse_unknown("field", &el.pos))),
    };
    let field_ctx = |r: Result<Field, E>| -> Result<Field, E> {
        r.map_err(|e| e.with(parsing("field", &name, &el.pos)))
    };
    field_ctx(async {
        let (offset, width) = if let Some(br) = el.child("bitRange") {
            crate::svd::parse_bit_range(&br.text).map_err(|e| {
                E::new(e.text())
            })?
        } else if el.child("bitOffset").is_some() {
            let off = el.child("bitOffset").unwrap();
            let w = el.child("bitWidth").ok_or_else(|| E::new(missing_tag("bitWidth")))?;
            let o = parse_int10(&off.text, off, "bitOffset")? as u32;
            let wd = parse_int10(&w.text, w, "bitWidth")? as u32;
            crate::svd::bit_range_from_offset_width(o, wd).map_err(|e| E::new(e.text()))?
        } else if el.child("msb").is_some() {
            let msb = el.child("msb").unwrap();
            let lsb = el.child("lsb").ok_or_else(|| E::new(missing_tag("lsb")))?;
            let m = parse_int10(&msb.text, msb, "msb")? as u32;
            let l = parse_int10(&lsb.text, lsb, "lsb")? as u32;
            crate::svd::parse_bit_range(&format!("[{}:{}]", m, l)).map_err(|e| E::new(e.text()))?
        } else {
            return Err(E::new("Bit range invalid, Syntax".to_string()));
        };
        let access = match el.child("access") {
            Some(a) => Some(Access::parse(&a.text, a)?),
            None => None,
        };
        let mut evs: Option<EnumeratedValues> = None;
        for e in el.children_of("enumeratedValues") {
            let parsed = parse_enumerated_values(e)?;
            if evs.is_none() {
                evs = Some(parsed);
            }
        }
        let dim = parse_dim(el, "field")?;
        Ok(Field {
            name,
            description: get_desc(el),
            offset,
            width,
            access,
            enumerated_values: evs,
            dim,
        })
    })
}

fn parse_enumerated_values(el: &Element) -> Result<EnumeratedValues, E> {
    let name = el.child_text("name");
    let usage = el.child_text("usage");
    let mut values = Vec::new();
    for v in el.children_of("enumeratedValue") {
        values.push(parse_enumerated_value(v)?);
    }
    Ok(EnumeratedValues {
        name,
        usage,
        values,
    })
}

fn parse_enumerated_value(el: &Element) -> Result<EnumeratedValue, E> {
    let name = match get_name(el) {
        Ok(n) => n,
        Err(e) => return Err(e.with(parse_unknown("enumeratedValue", &el.pos))),
    };
    let ctx = |r: Result<EnumeratedValue, E>| -> Result<EnumeratedValue, E> {
        r.map_err(|e| e.with(in_tag("enumeratedValue", &name)))
    };
    ctx(async {
        let value_el = el
            .child("value")
            .ok_or_else(|| E::new(missing_tag("value")))?;
        let value = parse_int(&value_el.text, value_el, "value")?;
        Ok(EnumeratedValue {
            name: Some(name),
            description: get_desc(el),
            value,
            is_default: el.child_text("isDefault") == "true",
        })
    })
}

fn parse_cluster(
    el: &Element,
    peri_size: u32,
    peri_access: Option<Access>,
    peri_reset: Option<u64>,
) -> Result<Cluster, E> {
    let name = match get_name(el) {
        Ok(n) => n,
        Err(e) => return Err(e.with(parse_unknown("cluster", &el.pos))),
    };
    let cluster_ctx = |r: Result<Cluster, E>| -> Result<Cluster, E> {
        r.map_err(|e| e.with(parsing("cluster", &name, &el.pos)))
    };
    cluster_ctx(async {
        let dim = parse_dim(el, "cluster")?;
        if dim.is_some() {
            require_percent(&name, "cluster", el)?;
        }
        if let Some(d) = &dim {
            check_dim_index(d, "cluster", &name, el)?;
        }
        let off_el = el
            .child("addressOffset")
            .ok_or_else(|| E::new(missing_tag("addressOffset")))?;
        let offset = parse_int(&off_el.text, off_el, "addressOffset")?;
        let size = match el.child("size") {
            Some(s) => parse_int(&s.text, s, "size")? as u32,
            None => peri_size,
        };
        let access = match el.child("access") {
            Some(a) => Some(Access::parse(&a.text, a)?),
            None => peri_access,
        };
        let reset_value = match el.child("resetValue") {
            Some(r) => Some(parse_int(&r.text, r, "resetValue")?),
            None => peri_reset,
        };
        let mut children = Vec::new();
        for c in &el.children {
            match c.name.as_str() {
                "register" => children.push(RegOrCluster::Reg(parse_register(c, size, access, reset_value)?)),
                "cluster" => children.push(RegOrCluster::Cluster(parse_cluster(c, size, access, reset_value)?)),
                _ => {}
            }
        }
        Ok(Cluster {
            name,
            description: get_desc(el),
            offset,
            size: Some(size),
            access,
            reset_value,
            dim,
            children,
            alternate_group: el.child_text("alternateGroup"),
        })
    })
}
