// SVD data model and parser.

use crate::xml::{Element, Pos, XmlError};
use crate::util::invalid_ident;

#[derive(Debug, Clone)]
pub struct E {
    pub items: Vec<String>,
}

impl E {
    pub fn new(msg: String) -> E {
        E { items: vec![msg] }
    }
    pub fn with(self, ctx: String) -> E {
        let mut e = self;
        e.items.push(ctx);
        e
    }
    /// Format like anyhow's `{:#}`: outermost first, numbered if more than one.
    pub fn text(&self) -> String {
        let mut out = String::new();
        let n = self.items.len();
        for (i, item) in self.items.iter().rev().enumerate() {
            if n > 1 {
                out.push_str(&format!("{}: {}", i, item));
            } else {
                out.push_str(item);
            }
            if i + 1 < n {
                out.push('\n');
            }
        }
        out
    }
}

pub fn missing_tag(tag: &str) -> String {
    format!("Expected a <{}> tag, found none", tag)
}
pub fn parse_unknown(tag: &str, pos: &Pos) -> String {
    format!("Parsing unknown {} at {}", tag, pos.to_string())
}
pub fn parsing(tag: &str, name: &str, pos: &Pos) -> String {
    format!("Parsing {} `{}` at {}", tag, name, pos.to_string())
}
pub fn in_tag(tag: &str, name: &str) -> String {
    format!("In {} `{}`", tag, name)
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Access {
    ReadOnly,
    WriteOnly,
    ReadWrite,
    ReadWriteOnce,
    WriteOnce,
}

impl Access {
    fn parse(s: &str, el: &Element) -> Result<Access, E> {
        match s {
            "read-only" => Ok(Access::ReadOnly),
            "write-only" => Ok(Access::WriteOnly),
            "read-write" => Ok(Access::ReadWrite),
            "read-writeOnce" => Ok(Access::ReadWriteOnce),
            "writeOnce" => Ok(Access::WriteOnce),
            _ => Err(E::new(format!(
                "unknown access variant '{}' found",
                s
            ))
            .with(parse_unknown("access", &el.pos))),
        }
    }
    pub fn readable(self) -> bool {
        matches!(self, Access::ReadOnly | Access::ReadWrite | Access::ReadWriteOnce)
    }
    pub fn writable(self) -> bool {
        matches!(
            self,
            Access::WriteOnly | Access::ReadWrite | Access::ReadWriteOnce | Access::WriteOnce
        )
    }
    pub fn short(self) -> &'static str {
        match self {
            Access::ReadOnly => "r",
            Access::WriteOnly | Access::WriteOnce => "w",
            Access::ReadWrite | Access::ReadWriteOnce => "rw",
        }
    }
}

fn parse_int(s: &str, el: &Element, tag: &str) -> Result<u64, E> {
    let t = s.trim();
    if t.is_empty() {
        return Err(E::new("Failed to parse `cannot parse integer from empty string`".to_string())
            .with(parse_unknown(tag, &el.pos)));
    }
    let t = if let Some(h) = t.strip_prefix("0x") {
        h
    } else if let Some(h) = t.strip_prefix("0X") {
        h
    } else {
        t
    };
    match u64::from_str_radix(t, 16) {
        Ok(v) => Ok(v),
        Err(_) => match u64::from_str_radix(t, 10) {
            Ok(v) => Ok(v),
            Err(_) => Err(E::new(
                "Failed to parse `invalid digit found in string`".to_string(),
            )
            .with(parse_unknown(tag, &el.pos))),
        },
    }
}

fn parse_int10(s: &str, el: &Element, tag: &str) -> Result<u64, E> {
    let t = s.trim();
    match t.parse::<u64>() {
        Ok(v) => Ok(v),
        Err(_) => Err(E::new(
            "Failed to parse `invalid digit found in string`".to_string(),
        )
        .with(parse_unknown(tag, &el.pos))),
    }
}

#[derive(Clone, Debug)]
