#[derive(Clone, Debug)]
pub struct Cluster {
    pub name: String,
    pub description: Option<String>,
    pub offset: u64,
    pub size: Option<u32>,
    pub access: Option<Access>,
    pub reset_value: Option<u64>,
    pub dim: Option<Dim>,
