// ---------------------------------------------------------------------------
// Bit range parsing
// ---------------------------------------------------------------------------

pub enum BitRangeError {
    Syntax,
    ParseError,
    Size,
    WidthZero,
}

impl BitRangeError {
    pub fn text(&self) -> String {
        match self {
            BitRangeError::Syntax => "Bit range invalid, Syntax".to_string(),
            BitRangeError::ParseError => "Bit range invalid, ParseError".to_string(),
            BitRangeError::Size => "Bit range invalid, Size".to_string(),
            BitRangeError::WidthZero => {
                "`BitRange error: bitRange width of 0 does not make sense".to_string()
            }
        }
    }
}

pub fn parse_bit_range(s: &str) -> Result<(u32, u32), BitRangeError> {
    let t = s.trim();
    if t.is_empty() || !t.starts_with('[') || !t.ends_with(']') {
        return Err(BitRangeError::ParseError);
    }
    let inner = &t[1..t.len() - 1];
    let parts: Vec<&str> = inner.split(':').collect();
    if parts.len() != 2 {
        return Err(BitRangeError::ParseError);
    }
    let msb = parts[0].trim();
    let lsb = parts[1].trim();
    if msb.is_empty() || lsb.is_empty() {
        return Err(BitRangeError::ParseError);
    }
    let m: u32 = match msb.parse() {
        Ok(v) => v,
        Err(_) => return Err(BitRangeError::ParseError),
    };
    let l: u32 = match lsb.parse() {
        Ok(v) => v,
        Err(_) => return Err(BitRangeError::ParseError),
    };
    if m < l {
        return Err(BitRangeError::Size);
    }
    let width = m - l + 1;
    if width == 0 {
        return Err(BitRangeError::WidthZero);
    }
    Ok((l, width))
}

pub fn bit_range_from_offset_width(off: u32, width: u32) -> Result<(u32, u32), BitRangeError> {
    if width == 0 {
        return Err(BitRangeError::WidthZero);
    }
    Ok((off, width))
}

