// Code generation: turning the parsed SVD into Rust sources.

use crate::cfg::{Config, Settings, Edition, Target};
use crate::ident::{format, format_ident, IdentFormat, IdentFormats};
use crate::svd::*;
use crate::log;

pub struct Rendered {
    pub lib: String,
    pub generic: Option<String>,
    pub device_x: String,
    pub features: Option<String>,
}

type R<T> = Result<T, E>;

fn gerr(msg: &str) -> E {
    E::new(msg.to_string())
}

// --- helpers -------------------------------------------------------------

fn hex_grouped(v: u64) -> String {
    if v == 0 {
        return "0".to_string();
    }
    let s = format!("{:x}", v);
    let mut padded = String::new();
    let rem = s.len() % 4;
    if rem != 0 {
        padded.push_str(&"0".repeat(4 - rem));
    }
    padded.push_str(&s);
    let mut out = String::from("0x");
    let n = padded.len();
    for (i, c) in padded.chars().enumerate() {
        out.push(c);
        if (i + 1) % 4 == 0 && i + 1 < n {
            out.push('_');
        }
    }
    out
}

fn hex_offset(v: u64) -> String {
    format!("{:#04x}", v)
}

fn mask_repr(width: u32) -> String {
    let mask: u64 = if width >= 64 {
        u64::MAX
    } else {
        (1u64 << width) - 1
    };
    if mask < 10 {
        return format!("{}", mask);
    }
    let d = (width + 3) / 4;
    if d <= 2 {
        return format!("{:#04x}", mask);
    }
    if d <= 4 {
        return format!("{:#06x}", mask);
    }
    let dd = ((d + 3) / 4) * 4;
    let s = format!("{:0width$x}", mask, width = dd);
    let mut out = String::from("0x");
    for (i, c) in s.chars().enumerate() {
        if i > 0 && i % 4 == 0 {
            out.push('_');
        }
        out.push(c);
    }
    out
}

fn rust_string_escape(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\0' => out.push_str("\\0"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{{{:x}}}", c as u32)),
            c => out.push(c),
        }
    }
    out
}

fn doc(s: &str) -> String {
    format!("#[doc = \"{}\"]", rust_string_escape(s))
}

fn doc_raw(s: &str) -> String {
    format!("#[doc = r\"{}\"]", s)
}

fn doc_alias(s: &str) -> String {
    format!("#[doc (alias = \"{}\")]", rust_string_escape(s))
}

fn ifmt(ident_formats: &IdentFormats, key: &str) -> IdentFormat {
    ident_formats
        .iter()
        .find(|(k, _)| k == key)
        .map(|(_, v)| v.clone())
        .unwrap_or(IdentFormat {
            case: None,
            prefix: String::new(),
            suffix: String::new(),
        })
}

fn fmt_id(ident_formats: &IdentFormats, key: &str, name: &str) -> String {
    format_ident(&ifmt(ident_formats, key), name)
}

fn fmt(ident_formats: &IdentFormats, key: &str, name: &str) -> String {
    format(&ifmt(ident_formats, key), name)
}

fn ux_for_width(w: u32) -> &'static str {
    match w {
        0..=8 => "u8",
        9..=16 => "u16",
        17..=32 => "u32",
        _ => "u64",
    }
}

fn ux_for_size(size: u32) -> &'static str {
    match size {
        0..=8 => "u8",
        9..=16 => "u16",
        17..=32 => "u32",
        _ => "u64",
    }
}
