{"command": "cd /workspace && cat >> src/gen.rs <<'RS'

// --- templates -----------------------------------------------------------

const CRATE_ATTRS: &str = include_str!("boiler/crate_attrs.txt");
const MID: &str = include_str!("boiler/mid.txt");
const GENERIC_RS: &str = include_str!("boiler/generic_rs.txt");
const ATOMICS: &str = include_str!("boiler/atomics.txt");
const ATOMICS_FEAT: &str = include_str!("boiler/atomics_feat.txt");
const GENERIC_MOD_DECL: &str =
    "#[doc = \"Common register and bit access and modify traits\"] pub mod generic ;";
const RISCV_MACRO: &str = include_str!("boiler/riscv_interrupt_macro.txt");

const FEATURES_HEADER: &str = "# Below are the FEATURES generated by svd2rust base on groupName in SVD file.\n# Please copy them to Cargo.toml.\n[features]\n";

const BUILD_RS: &str = "# ! [doc = r\" Builder file for Peripheral access crate generated by svd2rust tool\"] use std :: env ; use std :: fs :: File ; use std :: io :: Write ; use std :: path :: PathBuf ; fn main () { if env :: var_os (\"CARGO_FEATURE_RT\") . is_some () { let out = & PathBuf :: from (env :: var_os (\"OUT_DIR\") . unwrap ()) ; File :: create (out . join (\"device.x\")) . unwrap () . write_all (include_bytes ! (\"device.x\")) . unwrap () ; println ! (\"cargo:rustc-link-search={}\" , out . display ()) ; println ! (\"cargo:rerun-if-changed=device.x\") ; } println ! (\"cargo:rerun-if-changed=build.rs\") ; }\n";

pub fn generate(cfg: &Config, device: &Device, settings: &Settings) -> R<Rendered> {
    let ident_formats = &cfg.ident_formats;
    let mut out: Vec<String> = Vec::new();
    let target = cfg.target;
    let edition = cfg.edition;

    // --- crate attributes -------------------------------------------------
    if cfg.skip_crate_attributes {
        out.push("# [allow (unused_imports)] use generic :: * ;".to_string());
    } else {
        let mut attrs = String::new();
        if target == Target::Msp430 {
            attrs.push_str("# ! [feature (abi_msp430_interrupt)] ");
        }
        let desc = device
            .description
            .clone()
            .unwrap_or_else(|| device.name.clone());
        let _ = desc;
        let doc_str = format!("Peripheral access API for {} microcontrollers (generated using svd2rust v0.37.1 (63c65c2 2026-06-11))\\n\\nYou can find an overview of the generated API [here].\\n\\nAPI features to be included in the [next] svd2rust release can be generated by cloning the svd2rust [repository], checking out the above commit, and running `cargo doc --open`.\\n\\n[here]: https://docs.rs/svd2rust/0.37.1/svd2rust/#peripheral-api\\n[next]: https://github.com/rust-embedded/svd2rust/blob/master/CHANGELOG.md#unreleased\\n[repository]: https://github.com/rust-embedded/svd2rust", device.name);
        attrs.push_str(&format!(
            "# ! [doc = \"{}\"] # ! [allow (non_camel_case_types)] # ! [allow (non_snake_case)] # ! [no_std] # ! [cfg_attr (docsrs , feature (doc_cfg))]",
            doc_str
        ));
        if cfg.reexport_core_peripherals {
            attrs.push_str(" pub use cortex_m :: peripheral :: Peripherals as CorePeripherals ; pub use cortex_m :: peripheral :: { CBP , CPUID , DCB , DWT , FPB , FPU , ITM , MPU , NVIC , SCB , SYST , TPIU , } ;");
        }
        out.push(attrs);
        if !cfg.make_mod {
            out.push("#[allow (unused_imports)] use generic :: * ;".to_string());
        }
    }
    if cfg.reexport_interrupt {
        out.push("#[cfg (feature = \"rt\")] pub use cortex_m_rt :: interrupt ;".to_string());
        out.push(
            "#[cfg (feature = \"rt\")] pub use self :: Interrupt as interrupt ;".to_string(),
        );
    }
    if cfg.skip_crate_attributes && !cfg.make_mod {
        // the use generic line was already merged above
    } else {
        out.push("#[allow (unused_imports)] use generic :: * ;".to_string());
    }
    if cfg.generic_mod {
        out.push(GENERIC_MOD_DECL.to_string());
    } else {
        for line in MID.lines().skip(1) {
            out.push(line.to_string());
        }
    }
    if cfg.atomics {
        if let Some(feat) = &cfg.atomics_feature {
            let block = ATOMICS_FEAT.replace("atom", feat);
            for line in block.lines() {
                out.push(line.to_string());
            }
        } else {
            for line in ATOMICS.lines() {
                out.push(line.to_string());
            }
        }
    }
    render_interrupts(cfg, device, &mut out);

    // --- peripherals ------------------------------------------------------
    let mut periph_names: Vec<String> = Vec::new();
    let mut fields: Vec<(String, String, String)> = Vec::new(); // desc, cfg, field_name
    let mut steal_items: Vec<(String, String, String)> = Vec::new();
    for p in &device.peripherals {
        let expanded = expand_peripheral(p);
        let base_mod = fmt_id(ident_formats, "peripheral_mod", &strip_percent(&p.name));
        let is_derived = p.derive_from.is_some() && expanded.is_empty();
        let _ = is_derived;
        let _ = base_mod;
        for ep in &expanded {
            let block = render_peripheral(cfg, ep, p)?;
            out.push(block);
            let type_name = fmt_id(ident_formats, "peripheral", &ep.expanded_name);
            let field_name = fmt_id(ident_formats, "peripheral_mod", &ep.expanded_name);
            let _ = field_name;
            periph_names.push(type_name.clone());
            let desc = ep.description.clone().unwrap_or_default();
            let cfg_attr = if cfg.feature_peripheral {
                format!("#[cfg (feature = \"{}\")] ", fmt_id(ident_formats, "peripheral_feature", &ep.expanded_name))
            } else if cfg.feature_group {
                match &p.group_name {
                    Some(g) => format!("#[cfg (feature = \"{}\")] ", fmt_id(ident_formats, "peripheral_feature", g)),
                    None => String::new(),
                }
            } else {
                String::new()
            };
            let steal_cfg = steal_cfg_for(cfg, p, &ep.expanded_name);
            fields.push((desc, cfg_attr, snake(&ep.expanded_name)));
            steal_items.push((snake(&ep.expanded_name), type_name, steal_cfg));
        }
    }

    // --- Peripherals struct -----------------------------------------------
    let edition_unsafe = edition == Edition::E2024;
    let mut line = String::new();
    line.push_str("#[no_mangle] static mut DEVICE_PERIPHERALS : bool = false ;");
    out.push(line);
    out.push("#[doc = r\" All the peripherals.\"]".to_string());
    out.push("#[allow (non_snake_case)] pub struct Peripherals {".to_string());
    for (i, (desc, cfg_attr, field)) in fields.iter().enumerate() {
        let mut l = doc(desc);
        if !cfg_attr.is_empty() {
            l.push('\n');
            l.push_str(cfg_attr.trim_end());
        }
        if i + 1 < fields.len() {
            l.push_str(&format!(" pub {} : {} ,", field, periph_names[i]));
        } else {
            l.push_str(&format!(" pub {} : {} , }} impl Peripherals {{", field, periph_names[i]));
        }
        out.push(l);
    }
    out.push("#[doc = r\" Returns all the peripherals *once*.\"]".to_string());
    out.push("#[cfg (feature = \"critical-section\")]".to_string());
    out.push("#[inline] pub fn take () -> Option < Self > { critical_section :: with (| _ | { if unsafe { DEVICE_PERIPHERALS } { return None } Some (unsafe { Peripherals :: steal () }) }) }".to_string());
    out.push("#[doc = r\" Unchecked version of `Peripherals::take`.\"]".to_string());
    out.push("#[doc = r\"\"]".to_string());
    out.push("#[doc = r\" # Safety\"]".to_string());
    out.push("#[doc = r\"\"]".to_string());
    out.push("#[doc = r\" Each of the returned peripherals must be used at most once.\"]".to_string());
    let mut steal_line = String::from("#[inline] pub unsafe fn steal () -> Self { ");
    if edition_unsafe {
        steal_line.push_str("unsafe { DEVICE_PERIPHERALS = true } ");
    } else {
        steal_line.push_str("DEVICE_PERIPHERALS = true ; ");
    }
    steal_line.push_str("Peripherals { ");
    for (i, (field, type_name, cfg_attr)) in steal_items.iter().enumerate() {
        if !cfg_attr.is_empty() {
            if i > 0 {
                steal_line.push('\n');
            }
            steal_line.push_str(cfg_attr);
        }
        let val = if edition_unsafe {
            format!("unsafe {{ {} :: steal () }}", type_name)
        } else {
            format!("{} :: steal ()", type_name)
        };
        steal_line.push_str(&format!("{} : {} , ", field, val));
    }
    steal_line.push_str("} } }");
    out.push(steal_line);

    // --- device.x ---------------------------------------------------------
    let interrupts = device.interrupt_list();
    let mut max_val: u64 = 0;
    for i in &interrupts {
        if i.value > max_val {
            max_val = i.value;
        }
    }
    let n = (max_val + 1) as usize;
    let mut slots: Vec<Option<String>> = vec![None; n];
    for i in &interrupts {
        if (i.value as usize) < n {
            slots[i.value as usize] = Some(i.name.clone());
        }
    }
    let mut device_x = String::new();
    for s in slots.iter().flatten() {
        device_x.push_str(&format!("PROVIDE({} = DefaultHandler);\n", s));
    }

    // --- features.toml ----------------------------------------------------
    let mut features: Option<String> = None;
    if cfg.feature_group || cfg.feature_peripheral {
        let mut feats: Vec<String> = Vec::new();
        if cfg.feature_peripheral {
            for ep in device
                .peripherals
                .iter()
                .flat_map(|p| expand_peripheral(p))
            {
                let f = fmt_id(ident_formats, "peripheral_feature", &ep.expanded_name);
                if !feats.contains(&f) {
                    feats.push(f);
                }
            }
            feats.sort();
            let mut s = FEATURES_HEADER.to_string();
            for f in &feats {
                s.push_str(&format!("{} = []\n", f));
