// --- peripheral expansion ------------------------------------------------

pub struct ExpandedPeripheral {
    pub expanded_name: String,
    pub description: Option<String>,
    pub base_address: u64,
    pub peripheral: crate::svd::Peripheral,
}

fn expand_peripheral(p: &Peripheral) -> Vec<ExpandedPeripheral> {
    match &p.dim {
        None => vec![ExpandedPeripheral {
            expanded_name: p.name.clone(),
            description: p.description.clone(),
            base_address: p.base_address,
            peripheral: p.clone(),
        }],
        Some(dim) => {
            let base_name = strip_percent(&p.name);
            let mut out = Vec::new();
            for i in 0..dim.dim {
                let idx = match &dim.index {
                    Some(v) => v.get(i as usize).cloned().unwrap_or_else(|| i.to_string()),
                    None => i.to_string(),
                };
                let expanded_name = format!("{}{}", base_name, idx);
                let desc = p
                    .description
                    .clone()
                    .map(|d| d.replace("%s", &idx));
                out.push(ExpandedPeripheral {
                    expanded_name,
                    description: desc,
                    base_address: p.base_address + i * dim.increment,
                    peripheral: p.clone(),
                });
            }
            out
        }
    }
}

fn steal_cfg_for(cfg: &Config, p: &Peripheral, name: &str) -> String {
    if cfg.feature_peripheral {
        format!(
            "#[cfg (feature = \"{}\")]",
            fmt_id(&cfg.ident_formats, "peripheral_feature", name)
        )
    } else if cfg.feature_group {
        match &p.group_name {
            Some(g) => format!(
                "#[cfg (feature = \"{}\")]",
                fmt_id(&cfg.ident_formats, "peripheral_feature", g)
            ),
            None => String::new(),
        }
    } else {
        String::new()
    }
}
RS
echo ok"}

