// --- register block layout ----------------------------------------------

#[derive(Clone)]
struct Elem {
    name: String,        // base name (no %s)
    offset: u64,
    size: u64,           // size in bytes of a single element
    dim: Option<(u64, u64)>, // (count, increment)
    dim_index: Option<Vec<String>>,
    is_cluster: bool,
    index: usize, // index into the children list
}

fn elem_size_bytes(el: &RegOrCluster) -> u64 {
    match el {
        RegOrCluster::Reg(r) => r.size.unwrap_or(32) as u64 / 8,
        RegOrCluster::Cluster(c) => cluster_size(c),
    }
}

fn cluster_size(c: &Cluster) -> u64 {
    // compute the size of the cluster from its children
    let mut max_end: u64 = 0;
    for child in &c.children {
        let (off, sz) = match child {
            RegOrCluster::Reg(r) => {
                let s = elem_size_bytes(child);
                match &r.dim {
                    Some(d) => (r.offset, d.dim * d.increment),
                    None => (r.offset, s),
                }
            }
            RegOrCluster::Cluster(cc) => {
                let s = cluster_size(cc);
                match &cc.dim {
                    Some(d) => (cc.offset, d.dim * d.increment),
                    None => (cc.offset, s),
                }
            }
        };
        let end = off + sz;
        if end > max_end {
            max_end = end;
        }
    }
    max_end
}

fn contiguous_size(el: &RegOrCluster) -> u64 {
    match el {
        RegOrCluster::Reg(r) => r.size.unwrap_or(32) as u64 / 8,
        RegOrCluster::Cluster(c) => cluster_size(c),
    }
}

fn collect_elems(children: &[RegOrCluster]) -> Vec<Elem> {
    let mut out = Vec::new();
    for (i, c) in children.iter().enumerate() {
        let (name, offset, dim, dim_index) = match c {
            RegOrCluster::Reg(r) => (strip_percent(&r.name), r.offset, r.dim.clone(), r.dim.as_ref().and_then(|d| d.index.clone())),
            RegOrCluster::Cluster(c) => (strip_percent(&c.name), c.offset, c.dim.clone(), c.dim.as_ref().and_then(|d| d.index.clone())),
        };
        let dim = dim.map(|d| (d.dim, d.increment));
        out.push(Elem {
            name,
            offset,
            size: contiguous_size(c),
            dim,
            dim_index,
            is_cluster: matches!(c, RegOrCluster::Cluster(_)),
            index: i,
        });
    }
    out
}
RS
echo ok"}

