{"command": "cd /workspace && cat >> src/gen.rs <<'RS'

// --- accessors -----------------------------------------------------------

fn render_accessor(
    cfg: &Config,
    e: &Elem,
    offset: u64,
    single_group: bool,
    _periph_type: &str,
    contig: bool,
) -> R<String> {
    let ident_formats = &cfg.ident_formats;
    let name = fmt_id(ident_formats, "register_accessor", &e.name);
    let type_name = match e.is_cluster {
        true => fmt_id(ident_formats, "cluster", &e.name),
        false => fmt_id(ident_formats, "register", &e.name),
    };
    let desc = match e.is_cluster {
        true => {
            let c = &crate::CLUSTER_DESC;
            c
        }
        false => "",
    };
    let _ = desc;
    let mut out: Vec<String> = Vec::new();
    let (count, inc) = match e.dim {
        Some((d, i)) => (Some(d), Some(i)),
        None => (None, None),
    };
    if let Some(d) = count {
        let inc = inc.unwrap();
        let start = hex_offset(offset);
        let end = hex_offset(offset + d * inc);
        let array_doc = format!("{}..{} - {}", start, end, e.description());
        let mut l = doc(&array_doc);
        // dimIndex list => per index accessors + warning
        if let Some(idx) = &e.dim_index {
            if idx.len() > 1 || !idx.iter().all(|s| s.chars().all(|c| c.is_ascii_digit())) {
                l.push('\n');
                l.push_str(&doc(""));
                l.push('\n');
                let first = format!("{}{}", e.name, idx[0]);
                l.push_str(&doc(&format!(
                    "<div class=\\\"warning\\\">`n` is the index of register in the array. `n == 0` corresponds to `{}` register.</div>",
                    first
                )));
            }
        }
        let mut body = String::new();
        if contig {
            body = format!("& self . {} [n]", name);
        } else {
            l.push('\n');
            body = ptr_accessor(offset, Some(inc), true);
        }
        l.push_str(&format!(
            "#[inline (always)] pub const fn {} (& self , n : usize) -> & {} {{ {} }}",
            name, type_name, body
        ));
        out.push(l);
        out.push(doc("Iterator for array of:"));
        out.push(doc(&array_doc));
        let iter_body = if contig {
            format!("self . {} . iter ()", name)
        } else {
            format!(
                "(0 .. {}) . map (move | n | {})",
                d,
                ptr_accessor(offset, Some(inc), false)
            )
        };
        out.push(format!(
            "#[inline (always)] pub fn {}_iter (& self) -> impl Iterator < Item = & {} > {{ {} }}",
            name, type_name, iter_body
        ));
        // per index accessors
        if let Some(idx) = &e.dim_index {
            let is_list = !(idx.len() > 1 && idx.iter().all(|s| s.chars().all(|c| c.is_ascii_digit())));
            let _ = is_list;
            for (i, s) in idx.iter().enumerate() {
                let iname = fmt_id(
                    ident_formats,
                    "register_accessor",
                    &format!("{}{}", e.name, s),
                );
                out.push(doc(&format!(
                    "{} - {}",
                    hex_offset(offset + (i as u64) * inc),
                    e.description().replace("%s", s)
                )));
                out.push(format!(
                    "#[inline (always)] pub const fn {} (& self) -> & {} {{ self . {} ({}) }}",
                    iname, type_name, name, i
                ));
            }
        }
        return Ok(out.join("\n"));
    }
    // single element
    let mut l = doc(&format!("{} - {}", hex_offset(offset), e.description()));
    let body = if single_group {
        format!("& self . {}", name)
    } else {
        ptr_accessor(offset, None, false)
    };
    l.push_str(&format!(
        "#[inline (always)] pub const fn {} (& self) -> & {} {{ {} }}",
        name, type_name, body
    ));
    out.push(l);
    Ok(out.join("\n"))
}
RS
echo ok"}

