                "0".to_string()
            } else {
                hex_grouped(rv)
            },
            spec_name
        );
        if rv != 0 {
            line.push_str(&format!(
                " const RESET_VALUE : {} = {} ;",
                ux,
                hex_grouped(rv)
            ));
        }
        line.push_str(" }");
        out.push(line);
    }
    out.push("}".to_string());
    Ok(out.join("\n"))
}
RS
echo ok"}

