    let writable = reg.access.map(|a| a.writable()).unwrap_or(true);
    if readable {
        parts.push(format!(
            "You can [`read`](crate::Reg::read) this register and get [`{}::R`].",
            mod_name
        ));
    }
    if writable {
        if reg.reset_value.is_some() {
            parts.push(format!(
                "You can [`reset`](crate::Reg::reset), [`write`](crate::Reg::write), [`write_with_zero`](crate::Reg::write_with_zero) this register using [`{}::W`].",
                mod_name
            ));
        } else {
            parts.push(format!(
                "You can [`write_with_zero`](crate::Reg::write_with_zero) this register using [`{}::W`].",
                mod_name
            ));
        }
    }
    if readable && writable {
        parts.push("You can also [`modify`](crate::Reg::modify) this register.".to_string());
    }
    parts.push("See [API](https://docs.rs/svd2rust/#read--modify--write-api).".to_string());
    parts.join(" ")
}

fn render_register_mod(cfg: &Config, reg: &Register, elem: &Elem, periph_type: &str) -> R<String> {
    let ident_formats = &cfg.ident_formats;
    let settings = &cfg.settings;
    let raw_name = &reg.name;
    let stripped = strip_percent(raw_name);
    let eff_name = match (&reg.alternate_group, cfg.ignore_groups) {
        (Some(g), false) => format!("{}_{}", g, stripped),
        _ => stripped.clone(),
    };
    let type_name = fmt_id(ident_formats, "register", &eff_name);
    let mod_name = fmt_id(ident_formats, "register_mod", &eff_name);
    let spec_name = fmt(ident_formats, "register_spec", &stripped);
    let desc = reg.description.clone().unwrap_or_default();
    let access = reg.access.unwrap_or(Access::ReadWrite);
    let readable = access.readable();
    let writable = access.writable();

    let mut out: Vec<String> = Vec::new();
    let settings_doc = settings_register_doc(settings, periph_type, raw_name);
    let accessor_doc = format!(
        "{} ({}) register accessor: {}\\n\\n{}{}\\n\\nFor information about available fields see [`mod@{}`] module",
        eff_name,
        access.short(),
        desc,
        reg_methods(reg, &mod_name),
        settings_doc,
        mod_name
    );
    out.push(doc(&accessor_doc));
    out.push(format!(
        "{} pub type {} = crate :: Reg < {} :: {} > ;",
        doc_alias(&eff_name),
        type_name,
        mod_name,
        spec_name
    ));
    let mut line = doc(&desc);
    line.push_str(&format!(" pub mod {} {{", mod_name));
    out.push(line);

    // reader / writer type aliases
    let mut reader_line = doc(&format!("Register `{}` reader", raw_name));
    reader_line.push_str(&format!(
        " pub type R = crate :: R < {} > ;",
        spec_name
    ));
    let reader = readable;
    if reader {
        out.push(reader_line);
    }
    if writable {
        let mut writer_line = doc(&format!("Register `{}` writer", raw_name));
        writer_line.push_str(&format!(" pub type W = crate :: W < {} > ;", spec_name));
        out.push(writer_line);
    }

    let ux = ux_for_size(reg.size.unwrap_or(32));
    // per-field rendering
    struct Accessor {
        doc: String,
        name: String,
        ret: String,
        expr: String,
    }
    let mut reads: Vec<Accessor> = Vec::new();
    let mut writes: Vec<Accessor> = Vec::new();
    let mut reader_impl_lines: Vec<String> = Vec::new();
    let mut writer_impl_lines: Vec<String> = Vec::new();
    let mut debug_fields: Vec<String> = Vec::new();
    let reg_size = reg.size.unwrap_or(32);
    for f in &reg.fields {
        let facc = f.access.unwrap_or(access);
        let f_readable = facc.readable();
        let f_writable = facc.writable();
        let enum_name: Option<String> = f
            .enumerated_values
            .as_ref()
            .and_then(|ev| {
                ev.name
                    .as_ref()
                    .map(|n| fmt_id(ident_formats, "enum_name", n))
                    .or_else(|| Some(fmt_id(ident_formats, "enum_name", &f.name)))
            });
        let enum_name = match &f.enumerated_values {
            Some(ev) => match &ev.name {
                Some(n) => Some(fmt_id(ident_formats, "enum_name", n)),
                None => Some(fmt_id(ident_formats, "enum_name", &f.name)),
            },
            None => None,
        };
        let field_desc = f.description.clone().unwrap_or_default();
        let reader_alias = fmt(ident_formats, "field_reader", &f.name);
        let writer_alias = fmt(ident_formats, "field_writer", &f.name);
        let reader_alias_id = fmt_id(ident_formats, "field_reader", &f.name);
        let writer_alias_id = fmt_id(ident_formats, "field_writer", &f.name);
        let accessor_name = fmt_id(ident_formats, "field_accessor", &f.name);
        let is_bit = f.width == 1;
        let ux_f = ux_for_width(f.width);
        let enum_ux = match &enum_name {
            Some(_) => ux_f,
            None => ux_f,
        };
        let enum_ux = enum_ux;
        // enum definition
        if let Some(en) = &enum_name {
            let ev = f.enumerated_values.as_ref().unwrap();
            let reset_val = match reg.reset_value {
                Some(rv) => {
                    let mask: u64 = if f.width >= 64 {
                        u64::MAX
                    } else {
                        (1u64 << f.width) - 1
                    };
                    (rv >> f.offset) & mask
                }
                None => 0,
            };
            let enum_doc = format!(
                "{}\\n\\nValue on reset: {}",
                field_desc, reset_val
            );
            let mut l = doc(&enum_doc);
            l.push('\n');
            l.push_str("#[derive (Clone , Copy , Debug , PartialEq , Eq)]");
            l.push('\n');
            if !is_bit {
                l.push_str(&format!("#[repr ({})] ", enum_ux));
            }
            l.push_str(&format!("pub enum {} {{", en));
            for (i, v) in ev.values.iter().enumerate() {
                let vname = match &v.name {
                    Some(n) => fmt_id(ident_formats, "enum_value", n),
                    None => fmt_id(ident_formats, "enum_value", &format!("{}", v.value)),
                };
                let vdesc = match &v.description {
                    Some(d) => d.clone(),
                    None => format!(
                        "`{}`",
                        format!("{:b}", v.value)
                    ),
                };
                let mut vl = doc(&format!("{}: {}", v.value, vdesc));
                vl.push_str(&format!(" {} = {} ,", vname, v.value));
                if i + 1 == ev.values.len() {
                    if is_bit {
                        vl.push_str(" } impl From <");
                        vl.push_str(&format!(
                            " {} > for bool {{\n#[inline (always)] fn from (variant : {}) -> Self {{ variant as u8 != 0 }} }}",
                            en, en
                        ));
                    } else {
                        vl.push_str(&format!(" }} impl From < {} > for {} {{", en, enum_ux));
                        vl.push_str("\n#[inline (always)] fn from (variant : ");
                        vl.push_str(&format!(
                            "{}) -> Self {{ variant as _ }} }} impl crate :: FieldSpec for {} {{ type Ux = {} ; }} impl crate :: IsEnum for {} {{ }}",
                            en, en, enum_ux, en
                        ));
                    }
                }
                l.push('\n');
                l.push_str(&vl);
            }
            if ev.values.is_empty() {
                l.push_str(" }");
            }
            out.push(l);
        }
        // reader type alias + impl
        if f_readable {
            let gen = match (&enum_name, is_bit) {
                (Some(en), true) => format!(" < {} >", en),
                (Some(en), false) => format!(" < {} >", en),
                (None, true) => String::new(),
                (None, false) => {
                    if f.width > 8 {
                        format!(" < {} >", ux_f)
                    } else {
                        String::new()
                    }
                }
            };
            let mut l = doc(&format!("Field `{}` reader - {}", f.name, field_desc));
            l.push_str(&format!(
                " pub type {} = crate :: {}{} ;",
                reader_alias_id,
                if is_bit { "BitReader" } else { "FieldReader" },
                gen
            ));
            if let Some(en) = &enum_name {
                // variant + is_* methods
                let ev = f.enumerated_values.as_ref().unwrap();
                let mut impl_lines: Vec<String> = Vec::new();
                impl_lines.push(doc("Get enumerated values variant"));
                let mut arms: Vec<String> = Vec::new();
                for v in &ev.values {
                    let vname = match &v.name {
                        Some(n) => fmt_id(ident_formats, "enum_value", n),
                        None => fmt_id(ident_formats, "enum_value", &format!("{}", v.value)),
                    };
                    if is_bit {
                        arms.push(format!(
                            "{} => Some ({} :: {}) ,",
                            if v.value == 0 { "false" } else { "true" },
                            en,
                            vname
                        ));
                    } else {
                        arms.push(format!(
                            "{} => Some ({} :: {}) ,",
                            v.value, en, vname
                        ));
                    }
                }
                impl_lines.push(format!(
                    "#[inline (always)] pub const fn variant (& self) -> Option < {} > {{ match self . bits {{ {} _ => None , }} }}",
                    en,
                    arms.join(" ")
                ));
                for v in &ev.values {
                    let vname = match &v.name {
                        Some(n) => fmt_id(ident_formats, "enum_value", n),
                        None => fmt_id(ident_formats, "enum_value", &format!("{}", v.value)),
                    };
                    let vdesc = match &v.description {
                        Some(d) => d.clone(),
                        None => format!("`{}`", format!("{:b}", v.value)),
                    };
                    let acc = fmt_id(ident_formats, "enum_value_accessor", v.name.as_deref().unwrap_or(&format!("{}", v.value)));
                    impl_lines.push(doc(&vdesc));
                    impl_lines.push(format!(
                        "#[inline (always)] pub fn {} (& self) -> bool {{ * self == {} :: {} }}",
                        acc, en, vname
                    ));
                }
                let mut joined = impl_lines.join("\n");
                joined.push_str(" }");
                reader_impl_lines.push(format!("impl {} {{", reader_alias_id));
                reader_impl_lines.push(joined);
                out.push(l);
                for x in &reader_impl_lines[1..] {
                    out.push(x.clone());
                }
                reader_impl_lines.clear();
            } else {
                out.push(l);
            }
            // read accessor in impl R
            let mask = mask_repr(f.width);
            let full = f.width as u32 == reg_size;
            let expr = if is_bit {
                format!(
                    "((self . bits >> {}) & 1) != 0",
                    f.offset
                )
            } else {
                let cast = match (&enum_name, ux_f, ux) {
                    (Some(_), _, _) => "",
                    (None, a, b) => {
                        if a != b {
                            format!(" as {}", a)
                        } else {
                            String::new()
                        }
                    }
                };
                let mask_str = if full {
                    String::new()
                } else {
                    format!("& {}", mask)
                };
                if f.offset == 0 {
                    if full {
                        format!("self . bits")
                    } else {
                        format!("(self . bits {}){}", mask_str, cast)
                    }
                } else {
                    if full {
                        format!("self . bits >> {}", f.offset)
                    } else {
                        format!("((self . bits >> {}){}){}", f.offset, mask_str, cast)
                    }
                }
            };
            let doc_txt = if f.width == 1 {
                format!("Bit {}", f.offset)
            } else {
                format!("Bits {}:{}", f.offset, f.offset + f.width - 1)
            };
            let ret = match (&enum_name, is_bit) {
                (Some(_), _) => reader_alias_id.clone(),
                (None, true) => reader_alias_id.clone(),
                (None, false) => reader_alias_id.clone(),
            };
            reads.push(Accessor {
                doc: doc_txt,
                name: accessor_name.clone(),
                ret,
                expr,
            });
            debug_fields.push(accessor_name.clone());
        }
        // writer type alias + impl
        if f_writable {
            let gen = match (&enum_name, is_bit) {
                (Some(en), true) => format!(" < 'a , REG , {} > ", en),
                (Some(en), false) => format!(" < 'a , REG , {} , {} > ", f.width, en),
                (None, true) => String::from(" < 'a , REG > "),
                (None, false) => format!(" < 'a , REG , {} > ", f.width),
            };
            let mut l = doc(&format!("Field `{}` writer - {}", f.name, field_desc));
            l.push_str(&format!(
                " pub type {} < 'a , REG > = crate :: {}{} ;",
                writer_alias_id,
                if is_bit { "BitWriter" } else { "FieldWriter" },
                gen
            ));
            if let Some(en) = &enum_name {
                let ev = f.enumerated_values.as_ref().unwrap();
                let mut impl_lines: Vec<String> = Vec::new();
                for v in &ev.values {
                    let vname = match &v.name {
                        Some(n) => fmt_id(ident_formats, "enum_value", n),
                        None => fmt_id(ident_formats, "enum_value", &format!("{}", v.value)),
                    };
                    let vdesc = match &v.description {
                        Some(d) => d.clone(),
                        None => format!("`{}`", format!("{:b}", v.value)),
                    };
                    let acc = fmt_id(ident_formats, "enum_value_accessor", v.name.as_deref().unwrap_or(&format!("{}", v.value)));
                    impl_lines.push(doc(&vdesc));
                    impl_lines.push(format!(
                        "#[inline (always)] pub fn {} (self) -> & 'a mut crate :: W < REG > {{ self . variant ({} :: {}) }}",
                        acc, en, vname
                    ));
                }
                if !impl_lines.is_empty() {
                    let mut j = impl_lines.join("\n");
                    j.push_str(" }");
                    writer_impl_lines.push(j);
                    out.push(l);
                    out.push(format!(
                        "impl < 'a , REG > {} < 'a , REG > where REG : crate :: Writable + crate :: RegisterSpec ,{} {{",
                        writer_alias_id,
                        if is_bit {
                            String::new()
                        } else {
                            format!(" REG :: Ux : From < {} > ,", enum_ux)
                        }
                    ));
                    for x in &writer_impl_lines {
                        out.push(x.clone());
                    }
                    writer_impl_lines.clear();
                }
            } else {
                out.push(l);
            }
            let doc_txt = if f.width == 1 {
                format!("Bit {}", f.offset)
            } else {
                format!("Bits {}:{}", f.offset, f.offset + f.width - 1)
            };
            writes.push(Accessor {
                doc: doc_txt,
                name: accessor_name.clone(),
                ret: writer_alias_id.clone(),
                expr: format!("{} :: new (self , {})", writer_alias_id, f.offset),
            });
        }
    }
    // impl R / impl W
    if !reg.fields.is_empty() {
        if !reads.is_empty() {
            let mut block = String::from("impl R {\n");
            for (i, a) in reads.iter().enumerate() {
                let mut l = doc(&a.doc);
                l.push_str(&format!(
                    "\n#[inline (always)] pub fn {} (& self) -> {} {{ {} :: new ({}) }}",
                    a.name, a.ret, a.ret, a.expr
                ));
                if i + 1 == reads.len() {
                    if !writes.is_empty() {
                        l.push_str(" } impl W {");
                    } else {
                        l.push_str(" }");
                    }
                }
                block.push_str(&l);
                block.push('\n');
            }
            block.pop();
            out.push(block);
        }
        if !writes.is_empty() {
            let mut block = String::new();
            for (i, a) in writes.iter().enumerate() {
                let mut l = doc(&a.doc);
                l.push_str(&format!(
                    "\n#[inline (always)] pub fn {} (& mut self) -> {} < '_ , {} > {{ {} }}",
                    a.name, a.ret, spec_name, a.expr
                ));
                if i + 1 == writes.len() {
                    l.push_str(" }");
                }
                block.push_str(&l);
                block.push('\n');
            }
            block.pop();
            out.push(block);
        }
    } else if writable {
        out.push("impl W { }".to_string());
    }
    // Debug impls
    let debug_attr = match &cfg.impl_debug_feature {
        Some(f) => format!("#[cfg (feature = \"{}\")] ", f),
        None => String::new(),
    };
    if !readable {
        if cfg.impl_debug {
            out.push(format!(
                "{}impl core :: fmt :: Debug for crate :: generic :: Reg < {} > {{ fn fmt (& self , f : & mut core :: fmt :: Formatter < '_ >) -> core :: fmt :: Result {{ write ! (f , \"(not readable)\") }} }}",
                debug_attr, spec_name
            ));
        } else if reg.fields.is_empty() {
            out.push(format!(
                "impl core :: fmt :: Debug for crate :: generic :: Reg < {} > {{ fn fmt (& self , f : & mut core :: fmt :: Formatter < '_ >) -> core :: fmt :: Result {{ write ! (f , \"(not readable)\") }} }}",
                spec_name
            ));
        }
    } else if reg.fields.is_empty() {
        out.push("impl core :: fmt :: Debug for R { fn fmt (& self , f : & mut core :: fmt :: Formatter) -> core :: fmt :: Result { write ! (f , \"{}\" , self . bits ()) } }".to_string());
    } else if cfg.impl_debug {
        let mut fields_s = String::new();
        for (i, name) in debug_fields.iter().enumerate() {
            fields_s.push_str(&format!(
                " . field (\"{}\" , & self . {} ())",
                name, name
            ));
            let _ = i;
        }
        out.push(format!(
            "{}impl core :: fmt :: Debug for R {{ fn fmt (& self , f : & mut core :: fmt :: Formatter) -> core :: fmt :: Result {{ f . debug_struct (\"{}\"){} . finish () }} }}",
            debug_attr, raw_name, fields_s
        ));
    }
    // spec struct
    let spec_doc = format!(
        "{}\\n\\n{}{}",
        desc,
        reg_methods(reg, &mod_name),
        settings_doc
    );
    out.push(format!(
        "{} pub struct {} ; impl crate :: RegisterSpec for {} {{ type Ux = {} ; }}",
        doc(&spec_doc),
        spec_name,
        spec_name,
        ux
    ));
    if readable {
        out.push(format!(
            "#[doc = \"`read()` method returns [`{}::R`](R) reader structure\"] impl crate :: Readable for {} {{ }}",
            mod_name, spec_name
        ));
    }
    if writable {
        out.push(format!(
            "#[doc = \"`write(|w| ..)` method takes [`{}::W`](W) writer structure\"] impl crate :: Writable for {} {{ type Safety = crate :: Unsafe ; }}",
            mod_name, spec_name
        ));
    }
    if reg.reset_value.is_some() {
        let rv = reg.reset_value.unwrap();
        let mut line = format!(
            "#[doc = \"`reset()` method sets {} to value {}\"] impl crate :: Resettable for {} {{",
            raw_name,
            if rv == 0 {
                "0".to_string()
            } else {
                hex_grouped(rv)
            },
            spec_name
        );
        if rv != 0 {
            line.push_str(&format!(
                " const RESET_VALUE : {} = {} ;",
                ux,
                hex_grouped(rv)
            ));
        }
        line.push_str(" }");
        out.push(line);
    }
    out.push("}".to_string());
    Ok(out.join("\n"))
}
