                    None => fmt_id(ident_formats, "enum_value", &format!("{}", v.value)),
                };
                let vdesc = match &v.description {
                    Some(d) => d.clone(),
                    None => format!(
                        "`{}`",
                        format!("{:b}", v.value)
                    ),
                };
                let mut vl = doc(&format!("{}: {}", v.value, vdesc));
                vl.push_str(&format!(" {} = {} ,", vname, v.value));
                if i + 1 == ev.values.len() {
                    if is_bit {
                        vl.push_str(" } impl From <");
                        vl.push_str(&format!(
                            " {} > for bool {{\n#[inline (always)] fn from (variant : {}) -> Self {{ variant as u8 != 0 }} }}",
                            en, en
                        ));
                    } else {
                        vl.push_str(&format!(" }} impl From < {} > for {} {{", en, enum_ux));
                        vl.push_str("\n#[inline (always)] fn from (variant : ");
                        vl.push_str(&format!(
                            "{}) -> Self {{ variant as _ }} }} impl crate :: FieldSpec for {} {{ type Ux = {} ; }} impl crate :: IsEnum for {} {{ }}",
                            en, en, enum_ux, en
                        ));
                    }
                }
                l.push('\n');
                l.push_str(&vl);
            }
