                (Some(en), true) => format!(" < {} >", en),
                (Some(en), false) => format!(" < {} >", en),
                (None, true) => String::new(),
                (None, false) => {
                    if f.width > 8 {
                        format!(" < {} >", ux_f)
                    } else {
                        String::new()
                    }
                }
            };
            let mut l = doc(&format!("Field `{}` reader - {}", f.name, field_desc));
            l.push_str(&format!(
                " pub type {} = crate :: {}{} ;",
                reader_alias_id,
                if is_bit { "BitReader" } else { "FieldReader" },
                gen
            ));
            if let Some(en) = &enum_name {
                // variant + is_* methods
                let ev = f.enumerated_values.as_ref().unwrap();
                let mut impl_lines: Vec<String> = Vec::new();
                impl_lines.push(doc("Get enumerated values variant"));
                let mut arms: Vec<String> = Vec::new();
                for v in &ev.values {
                    let vname = match &v.name {
                        Some(n) => fmt_id(ident_formats, "enum_value", n),
                        None => fmt_id(ident_formats, "enum_value", &format!("{}", v.value)),
                    };
                    if is_bit {
                        arms.push(format!(
                            "{} => Some ({} :: {}) ,",
                            if v.value == 0 { "false" } else { "true" },
                            en,
                            vname
                        ));
                    } else {
                        arms.push(format!(
                            "{} => Some ({} :: {}) ,",
                            v.value, en, vname
                        ));
                    }
                }
                impl_lines.push(format!(
                    "#[inline (always)] pub const fn variant (& self) -> Option < {} > {{ match self . bits {{ {} _ => None , }} }}",
                    en,
                    arms.join(" ")
                ));
                for v in &ev.values {
                    let vname = match &v.name {
                        Some(n) => fmt_id(ident_formats, "enum_value", n),
                        None => fmt_id(ident_formats, "enum_value", &format!("{}", v.value)),
                    };
                    let vdesc = match &v.description {
