                        None => format!("`{}`", format!("{:b}", v.value)),
                    };
                    let acc = fmt_id(ident_formats, "enum_value_accessor", v.name.as_deref().unwrap_or(&format!("{}", v.value)));
                    impl_lines.push(doc(&vdesc));
                    impl_lines.push(format!(
                        "#[inline (always)] pub fn {} (& self) -> bool {{ * self == {} :: {} }}",
                        acc, en, vname
                    ));
                }
                let mut joined = impl_lines.join("\n");
                joined.push_str(" }");
                reader_impl_lines.push(format!("impl {} {{", reader_alias_id));
                reader_impl_lines.push(joined);
