                    f.offset
                )
            } else {
                let cast = match (&enum_name, ux_f, ux) {
                    (Some(_), _, _) => "",
                    (None, a, b) => {
                        if a != b {
                            format!(" as {}", a)
                        } else {
                            String::new()
                        }
                    }
                };
                let mask_str = if full {
                    String::new()
                } else {
                    format!("& {}", mask)
                };
                if f.offset == 0 {
                    if full {
                        format!("self . bits")
                    } else {
                        format!("(self . bits {}){}", mask_str, cast)
                    }
                } else {
                    if full {
                        format!("self . bits >> {}", f.offset)
                    } else {
                        format!("((self . bits >> {}){}){}", f.offset, mask_str, cast)
                    }
                }
            };
            let doc_txt = if f.width == 1 {
                format!("Bit {}", f.offset)
            } else {
                format!("Bits {}:{}", f.offset, f.offset + f.width - 1)
            };
            let ret = match (&enum_name, is_bit) {
                (Some(_), _) => reader_alias_id.clone(),
                (None, true) => reader_alias_id.clone(),
                (None, false) => reader_alias_id.clone(),
            };
