                (None, true) => String::from(" < 'a , REG > "),
                (None, false) => format!(" < 'a , REG , {} > ", f.width),
            };
            let mut l = doc(&format!("Field `{}` writer - {}", f.name, field_desc));
            l.push_str(&format!(
                " pub type {} < 'a , REG > = crate :: {}{} ;",
                writer_alias_id,
                if is_bit { "BitWriter" } else { "FieldWriter" },
                gen
            ));
            if let Some(en) = &enum_name {
                let ev = f.enumerated_values.as_ref().unwrap();
                let mut impl_lines: Vec<String> = Vec::new();
                for v in &ev.values {
                    let vname = match &v.name {
                        Some(n) => fmt_id(ident_formats, "enum_value", n),
                        None => fmt_id(ident_formats, "enum_value", &format!("{}", v.value)),
                    };
                    let vdesc = match &v.description {
                        Some(d) => d.clone(),
                        None => format!("`{}`", format!("{:b}", v.value)),
                    };
                    let acc = fmt_id(ident_formats, "enum_value_accessor", v.name.as_deref().unwrap_or(&format!("{}", v.value)));
                    impl_lines.push(doc(&vdesc));
                    impl_lines.push(format!(
                        "#[inline (always)] pub fn {} (self) -> & 'a mut crate :: W < REG > {{ self . variant ({} :: {}) }}",
                        acc, en, vname
                    ));
                }
                if !impl_lines.is_empty() {
                    let mut j = impl_lines.join("\n");
                    j.push_str(" }");
                    writer_impl_lines.push(j);
                    out.push(l);
                    out.push(format!(
                        "impl < 'a , REG > {} < 'a , REG > where REG : crate :: Writable + crate :: RegisterSpec ,{} {{",
                        writer_alias_id,
                        if is_bit {
                            String::new()
                        } else {
                            format!(" REG :: Ux : From < {} > ,", enum_ux)
                        }
                    ));
                    for x in &writer_impl_lines {
                        out.push(x.clone());
                    }
                    writer_impl_lines.clear();
                }
            } else {
                out.push(l);
            }
            let doc_txt = if f.width == 1 {
                format!("Bit {}", f.offset)
            } else {
                format!("Bits {}:{}", f.offset, f.offset + f.width - 1)
            };
            writes.push(Accessor {
                doc: doc_txt,
                name: accessor_name.clone(),
                ret: writer_alias_id.clone(),
                expr: format!("{} :: new (self , {})", writer_alias_id, f.offset),
            });
        }
    }
    // impl R / impl W
    if !reg.fields.is_empty() {
        if !reads.is_empty() {
            let mut block = String::from("impl R {\n");
            for (i, a) in reads.iter().enumerate() {
                let mut l = doc(&a.doc);
                l.push_str(&format!(
                    "\n#[inline (always)] pub fn {} (& self) -> {} {{ {} :: new ({}) }}",
                    a.name, a.ret, a.ret, a.expr
                ));
                if i + 1 == reads.len() {
                    if !writes.is_empty() {
                        l.push_str(" } impl W {");
                    } else {
                        l.push_str(" }");
                    }
                }
                block.push_str(&l);
                block.push('\n');
            }
            block.pop();
            out.push(block);
        }
        if !writes.is_empty() {
            let mut block = String::new();
            for (i, a) in writes.iter().enumerate() {
                let mut l = doc(&a.doc);
                l.push_str(&format!(
                    "\n#[inline (always)] pub fn {} (& mut self) -> {} < '_ , {} > {{ {} }}",
                    a.name, a.ret, spec_name, a.expr
                ));
                if i + 1 == writes.len() {
                    l.push_str(" }");
                }
                block.push_str(&l);
                block.push('\n');
            }
            block.pop();
            out.push(block);
        }
    } else if writable {
        out.push("impl W { }".to_string());
    }
    // Debug impls
    let debug_attr = match &cfg.impl_debug_feature {
        Some(f) => format!("#[cfg (feature = \"{}\")] ", f),
        None => String::new(),
    };
    if !readable {
        if cfg.impl_debug {
            out.push(format!(
                "{}impl core :: fmt :: Debug for crate :: generic :: Reg < {} > {{ fn fmt (& self , f : & mut core :: fmt :: Formatter < '_ >) -> core :: fmt :: Result {{ write ! (f , \"(not readable)\") }} }}",
                debug_attr, spec_name
            ));
        } else if reg.fields.is_empty() {
            out.push(format!(
                "impl core :: fmt :: Debug for crate :: generic :: Reg < {} > {{ fn fmt (& self , f : & mut core :: fmt :: Formatter < '_ >) -> core :: fmt :: Result {{ write ! (f , \"(not readable)\") }} }}",
                spec_name
            ));
        }
    } else if reg.fields.is_empty() {
        out.push("impl core :: fmt :: Debug for R { fn fmt (& self , f : & mut core :: fmt :: Formatter) -> core :: fmt :: Result { write ! (f , \"{}\" , self . bits ()) } }".to_string());
    } else if cfg.impl_debug {
        let mut fields_s = String::new();
        for (i, name) in debug_fields.iter().enumerate() {
            fields_s.push_str(&format!(
                " . field (\"{}\" , & self . {} ())",
                name, name
            ));
            let _ = i;
        }
        out.push(format!(
            "{}impl core :: fmt :: Debug for R {{ fn fmt (& self , f : & mut core :: fmt :: Formatter) -> core :: fmt :: Result {{ f . debug_struct (\"{}\"){} . finish () }} }}",
            debug_attr, raw_name, fields_s
        ));
    }
    // spec struct
    let spec_doc = format!(
        "{}\\n\\n{}{}",
        desc,
        reg_methods(reg, &mod_name),
        settings_doc
    );
    out.push(format!(
        "{} pub struct {} ; impl crate :: RegisterSpec for {} {{ type Ux = {} ; }}",
        doc(&spec_doc),
        spec_name,
        spec_name,
        ux
    ));
    if readable {
        out.push(format!(
            "#[doc = \"`read()` method returns [`{}::R`](R) reader structure\"] impl crate :: Readable for {} {{ }}",
            mod_name, spec_name
        ));
    }
    if writable {
        out.push(format!(
            "#[doc = \"`write(|w| ..)` method takes [`{}::W`](W) writer structure\"] impl crate :: Writable for {} {{ type Safety = crate :: Unsafe ; }}",
            mod_name, spec_name
        ));
    }
    if reg.reset_value.is_some() {
        let rv = reg.reset_value.unwrap();
        let mut line = format!(
            "#[doc = \"`reset()` method sets {} to value {}\"] impl crate :: Resettable for {} {{",
            raw_name,
            if rv == 0 {
                "0".to_string()
            } else {
                hex_grouped(rv)
            },
            spec_name
        );
        if rv != 0 {
            line.push_str(&format!(
                " const RESET_VALUE : {} = {} ;",
                ux,
                hex_grouped(rv)
            ));
        }
        line.push_str(" }");
        out.push(line);
    }
    out.push("}".to_string());
    Ok(out.join("\n"))
}
