fn render_cluster_mod(cfg: &Config, cl: &Cluster, elem: &Elem) -> R<String> {
    let ident_formats = &cfg.ident_formats;
    let stripped = strip_percent(&cl.name);
    let type_name = fmt_id(ident_formats, "cluster", &stripped);
    let mod_name = fmt_id(ident_formats, "cluster_mod", &stripped);
    let desc = cl.description.clone().unwrap_or_default();
    let mut out: Vec<String> = Vec::new();
    out.push(format!(
        "{} pub use self :: {} :: {} ;",
        doc(&desc),
        mod_name,
        type_name
    ));
    out.push(doc_raw("Cluster"));
    let mut l = doc(&desc);
    l.push_str(&format!(" pub mod {} {{", mod_name));
    out.push(l);
    out.push("#[repr (C)]".to_string());
    let mut fields: Vec<String> = Vec::new();
    let children = &cl.children;
    let elems = collect_elems(children);
    let mut sorted: Vec<Elem> = elems.clone();
    sorted.sort_by_key(|e| e.offset);
    let mut groups: Vec<(u64, Vec<usize>)> = Vec::new();
    for (i, e) in sorted.iter().enumerate() {
        if let Some(last) = groups.last_mut() {
            if last.0 == e.offset {
                last.1.push(i);
                continue;
            }
        }
        groups.push((e.offset, vec![i]));
    }
    let mut accessors: Vec<String> = Vec::new();
    let mut prev_end: u64 = 0;
    for (gi, (off, idxs)) in groups.iter().enumerate() {
        let gap = off.saturating_sub(prev_end);
        if gap > 0 {
            fields.push(format!("_reserved{} : [u8 ; {}]", gi, hex_grouped(gap)));
        }
        if idxs.len() > 1 {
            let first = &sorted[idxs[0]];
            let max_size = idxs
                .iter()
                .map(|i| {
                    let e = &sorted[*i];
                    match e.dim {
                        Some((d, inc)) => d * inc,
                        None => e.size,
                    }
                })
                .max()
                .unwrap_or(0);
            fields.push(format!(
                "_reserved{}_{} : [u8 ; {}]",
                gi,
                fmt(ident_formats, "cluster_accessor", &first.name),
                hex_grouped(max_size)
            ));
            for i in idxs.iter().rev() {
                let e = &sorted[*i];
                accessors.push(render_accessor(cfg, e, off, false, &type_name, false)?);
            }
        } else {
            let i = idxs[0];
            let e = &sorted[i];
            let (count, inc) = match e.dim {
                Some((d, inc)) => (Some(d), Some(inc)),
                None => (None, None),
            };
            let contig = match (count, inc) {
                (Some(d), Some(i)) => i == e.size,
                _ => true,
            };
            match (count, contig) {
                (Some(d), true) => {
                    fields.push(format!(
                        "{} : [{} ; {}]",
                        fmt_id(ident_formats, "cluster_accessor", &e.name),
                        fmt_id(ident_formats, "cluster", &e.name),
                        d
                    ));
                }
                (Some(_), false) => {
                    fields.push(format!(
                        "{} : ()",
                        fmt_id(ident_formats, "cluster_accessor", &e.name)
                    ));
                }
                _ => {
                    fields.push(format!(
                        "{} : {}",
                        fmt_id(ident_formats, "cluster_accessor", &e.name),
                        fmt_id(ident_formats, "cluster", &e.name)
                    ));
                }
            }
            accessors.push(render_accessor(cfg, e, off, true, &type_name, contig)?);
        }
        let end = idxs
            .iter()
            .map(|i| {
                let e = &sorted[*i];
                match e.dim {
                    Some((d, inc)) => off + d * inc,
                    None => off + e.size,
                }
            })
            .max()
            .unwrap_or(off);
        if end > prev_end {
            prev_end = end;
        }
    }
    let mut l = doc(&desc);
    if !cl.dim.is_some() {
        l.push('\n');
        l.push_str(&doc_alias(&stripped));
    }
    l.push_str(&format!(
        " pub struct {} {{ {} }} impl {} {{",
        type_name,
        fields.join(" , "),
        type_name
    ));
    out.push(l);
    for a in accessors {
        out.push(a);
    }
    out.push("}".to_string());
    for (i, c) in children.iter().enumerate() {
        let e = &elems[i];
        match c {
            RegOrCluster::Reg(r) => out.push(render_register_mod(cfg, r, e, &type_name)?),
            RegOrCluster::Cluster(cc) => out.push(render_cluster_mod(cfg, cc, e)?),
        }
    }
    out.push("}".to_string());
    Ok(out.join("\n"))
}
