fn render_interrupts(cfg: &Config, device: &Device, out: &mut Vec<String>) {
    let target = cfg.target;
    let edition = cfg.edition;
    let interrupts = device.interrupt_list();
    let mut max_val: u64 = 0;
    for i in &interrupts {
        if i.value > max_val {
            max_val = i.value;
        }
    }
    let n = (max_val + 1) as usize;
    let mut slots: Vec<Option<String>> = vec![None; n];
    for i in &interrupts {
        if (i.value as usize) < n {
            slots[i.value as usize] = Some(i.name.clone());
        }
    }
    if target == Target::Mips || target == Target::None {
        if interrupts.is_empty() {
            return;
        }
    }
    let unsafe_kw = edition == Edition::E2024;
    let section = cfg
        .interrupt_link_section
        .clone()
        .unwrap_or_else(|| ".vector_table.interrupts".to_string());
    match target {
        Target::CortexM | Target::Msp430 | Target::Riscv | Target::XtensaLx => {
            let abi = match target {
                Target::Msp430 => "msp430-interrupt",
                _ => "C",
            };
            let mut extern_line = String::from("#[cfg (feature = \"rt\")] ");
            if unsafe_kw {
                extern_line.push_str("unsafe ");
            }
            extern_line.push_str(&format!("extern \"{}\" {{", abi));
            for h in slots.iter().flatten() {
                let name = fmt_id(&cfg.ident_formats, "interrupt", h);
                extern_line.push_str(&format!(" fn {} () ;", name));
            }
            extern_line.push_str(" }");
            out.push(extern_line);
            out.push("#[doc (hidden)]".to_string());
            let pub_handler = match target {
                Target::Riscv | Target::XtensaLx => "pub ",
                _ => "",
            };
            let pub_reserved = match target {
                Target::Riscv => "pub ",
                _ => "",
            };
            let reserved_ty = match target {
                Target::Msp430 => "u16",
                Target::Riscv => "usize",
                _ => "u32",
            };
            let mut union = String::from("#[repr (C)] pub union Vector { ");
            union.push_str(&format!(
                "{}_handler : {}extern \"{}\" fn () ,",
                pub_handler,
                if unsafe_kw { "unsafe " } else { "" },
                abi
            ));
            union.push_str(&format!(" {}_reserved : {} , }}", pub_reserved, reserved_ty));
            out.push(union);
            out.push("#[cfg (feature = \"rt\")]".to_string());
            out.push("#[doc (hidden)]".to_string());
            match target {
                Target::CortexM | Target::Msp430 => {
                    if unsafe_kw {
                        out.push(format!(
                            "#[unsafe (link_section = \"{}\")]",
                            section
                        ));
                    } else {
                        out.push(format!("#[link_section = \"{}\"]", section));
                    }
                }
                _ => {}
            }
            let static_name = match target {
                Target::Riscv => "__EXTERNAL_INTERRUPTS",
                _ => "__INTERRUPTS",
            };
            let mut entries: Vec<String> = Vec::new();
            for s in &slots {
                match s {
                    Some(name) => {
                        let name = fmt_id(&cfg.ident_formats, "interrupt", name);
                        entries.push(format!("Vector {{ _handler : {} }}", name));
                    }
                    None => entries.push("Vector { _reserved : 0 }".to_string()),
                }
            }
            let arr = if entries.is_empty() {
                "[]".to_string()
            } else {
                format!("[{} ,]", entries.join(" , "))
            };
            match target {
                Target::Msp430 => {
                    out.push("#[no_mangle]".to_string());
                    out.push(format!(
                        "#[used] pub static {} : [Vector ; {}] = {} ;",
                        static_name, n, arr
                    ));
                }
                _ => {
                    if unsafe_kw {
                        out.push(format!("#[unsafe (no_mangle)] pub static {} : [Vector ; {}] = {} ;", static_name, n, arr));
                    } else {
                        out.push(format!(
                            "#[no_mangle] pub static {} : [Vector ; {}] = {} ;",
                            static_name, n, arr
                        ));
                    }
                }
            }
            if target == Target::Riscv && interrupts.is_empty() {
                return;
            }
            if target == Target::Riscv || target == Target::Mips {
                out.push("#[doc (hidden)] pub mod interrupt {".to_string());
            }
            let enum_doc = match target {
                Target::Msp430 => "Enumeration of all the interrupts. This enum is seldom used in application or library crates. It is present primarily for documenting the device's implemented interrupts.",
                _ => "Enumeration of all the interrupts.",
            };
            out.push(doc_raw(enum_doc));
            let mut l = String::from("#[derive (Copy , Clone , Debug , PartialEq , Eq)]");
            if !interrupts.is_empty() {
                l.push_str("\n#[repr (u16)] ");
            } else {
                l.push(' ');
            }
            l.push_str("pub enum Interrupt {");
            out.push(l);
            for (i, s) in slots.iter().enumerate() {
                if let Some(name) = s {
                    let name = fmt_id(&cfg.ident_formats, "interrupt", name);
                    let desc = interrupts
                        .iter()
                        .find(|iv| iv.name == name && iv.value == i as u64)
                        .and_then(|iv| iv.description.clone())
                        .unwrap_or_default();
                    out.push(format!(
                        "{} {} = {} ,",
                        doc(&format!("{} - {}", i, desc)),
                        name,
                        i
                    ));
                }
            }
            let closing = if interrupts.is_empty() {
                "} ".to_string()
            } else {
                "} ".to_string()
            };
            match target {
                Target::CortexM => {
                    let body = if interrupts.is_empty() {
                        "match self { }"
                    } else {
                        "self as u16"
                    };
                    let mut l = closing;
                    l.push_str("unsafe impl cortex_m :: interrupt :: InterruptNumber for Interrupt {");
                    out.push(l);
                    out.push(format!(
                        "#[inline (always)] fn number (self) -> u16 {{ {} }} }}",
                        body
                    ));
                }
                Target::Msp430 => {
                    out.push("}".to_string());
                }
                Target::Riscv | Target::XtensaLx | Target::Mips => {
                    out.push("}".to_string());
                    out.push(doc_raw(" TryFromInterruptError"));
                    out.push("#[derive (Debug , Copy , Clone)] pub struct TryFromInterruptError (()) ; impl Interrupt {".to_string());
                    out.push(doc_raw(" Attempt to convert a given value into an `Interrupt`"));
                    let mut arms = String::new();
                    for (i, s) in slots.iter().enumerate() {
                        if let Some(name) = s {
                            let name = fmt_id(&cfg.ident_formats, "interrupt", name);
                            arms.push_str(&format!("{} => Ok (Interrupt :: {}) , ", i, name));
                        }
                    }
                    let val_ty = match target {
                        Target::Riscv | Target::Mips => "u8",
                        _ => "u16",
                    };
                    let mut line = format!(
                        "#[inline] pub fn try_from (value : {}) -> Result < Self , TryFromInterruptError > {{ match value {{ {}_ => Err (TryFromInterruptError (())) , }} }}",
                        val_ty, arms
                    );
                    if target == Target::Mips {
                        line.push_str(" } }");
                    }
                    out.push(line);
                    if target == Target::Riscv {
                        for line in RISCV_MACRO.lines() {
                            out.push(line.to_string());
                        }
                        out.push("} } } pub use self :: interrupt :: Interrupt ;".to_string());
                    } else if target == Target::Mips {
                        out.push("pub use self :: interrupt :: Interrupt ;".to_string());
                    }
                }
            }
        }
        _ => {}
    }
}
