{"command": "cd /workspace && cat > src/main.rs <<'RS'
mod cfg;
mod cli;
mod gen;
mod ident;
mod log;
mod svd;
mod toml;
mod util;
mod yaml;
mod xml;

use cfg::{Config, Settings};
use log::{log, Level};
use std::io::Read;

fn main() {
    let cli = match cli::parse() {
        Ok(c) => c,
        Err(e) => match e {
            cli::CliOut::Out(s) => {
                print!("{}", s);
                std::process::exit(0);
            }
            cli::CliOut::Err(s) => {
                eprint!("{}", s);
                std::process::exit(2);
            }
        },
    };
    let mut config = cli;

    // The base address shift option is deserialized separately, and always
    // fails to deserialize from the command line string.
    if config.base_address_shift_cli.is_some() {
        log_plain(
            &format!(
                "Failed to deserialize value\n\nCaused by:\n    invalid type: string \"{}\", expected u64",
                config.base_address_shift_cli.as_ref().unwrap()
            ),
        );
        std::process::exit(1);
    }

    // --- TOML config file -------------------------------------------------
    if let Some(path) = &config.config_path {
        let content = match std::fs::read_to_string(path) {
            Ok(c) => c,
            Err(e) => {
                log_plain(&format!("Cannot open the config file\n\nCaused by:\n    {}", e));
                std::process::exit(1);
            }
        };
        match toml::parse(&content) {
            Ok(table) => match crate::cfg::apply_toml(&mut config.config, &table) {
                Ok(()) => {}
                Err(msg) => {
                    log_plain(&format!(
                        "Failed to deserialize value\n\nCaused by:\n    {}",
                        msg
                    ));
                    std::process::exit(1);
                }
            },
            Err(e) => {
                log_plain(&format!(
                    "Failed to parse value for parser #2\n\nCaused by:\n    0: Failed parse TOML\n    1: {}",
                    e.text(&content)
                ));
                std::process::exit(1);
            }
        }
    }

    // --- logger -----------------------------------------------------------
    let level = config
        .config
        .log_level
        .as_ref()
        .and_then(|l| Level::parse(l))
        .or_else(|| {
            std::env::var("RUST_LOG")
                .ok()
                .and_then(|l| Level::parse(l))
        })
        .unwrap_or(Level::Info);
    log::set_level(level);

    cfg::log_debug_config(&config.config);

    // --- settings file ----------------------------------------------------
    let mut settings = Settings {
        html_url: None,
        crate_path: None,
        riscv_config: None,
    };
    if let Some(path) = &config.settings_path {
        let content = match std::fs::read_to_string(path) {
            Ok(c) => c,
            Err(e) => {
                log(
                    Level::Error,
                    "svd2rust",
                    &format!("could not parse settings file\n\nCaused by:\n    {}", e),
                );
                std::process::exit(1);
            }
        };
        match yaml::parse(&content) {
            Ok(v) => {
                if let Err(msg) = crate::cfg::apply_yaml(&mut settings, &v) {
                    log(
                        Level::Error,
                        "svd2rust",
                        &format!(
                            "could not parse settings file\n\nCaused by:\n    {}",
                            msg
                        ),
                    );
                    std::process::exit(1);
                }
            }
            Err(e) => {
                log(
                    Level::Error,
                    "svd2rust",
                    &format!(
                        "could not parse settings file\n\nCaused by:\n    {}",
                        e.msg
                    ),
                );
                std::process::exit(1);
            }
        }
    }
    config.config.settings = settings;
    if let Some(rc) = &config.config.settings.riscv_config {
        if rc.base_isa.is_none() {
            log(
                Level::Warn,
                "svd2rust::config::riscv",
                "No base RISC-V ISA specified in settings file.",
            );
            log(
                Level::Warn,
                "svd2rust::config::riscv",
                "If your target supports vectored mode, you must specify the base ISA.",
            );
            log(
                Level::Warn,
                "svd2rust::config::riscv",
                "Otherwise, `riscv-rt` macros will not provide start trap routines to core interrupt handlers",
            );
        }
    }

    // --- input ------------------------------------------------------------
    log(Level::Info, "svd2rust", "Parsing device from SVD file");
    let input: String = match &config.config.input {
        Some(path) => match std::fs::read_to_string(path) {
            Ok(c) => c,
            Err(e) => {
                log(
                    Level::Error,
                    "svd2rust",
                    &format!("Cannot open the SVD file\n\nCaused by:\n    {}", e),
                );
                std::process::exit(1);
            }
        },
        None => {
            let mut s = String::new();
            let _ = std::io::stdin().read_to_string(&mut s);
            s
        }
    };

    let device = match crate::svd::parse(&input) {
        Ok(d) => d,
        Err(e) => {
            log(
                Level::Error,
                "svd2rust",
                &format!("Error parsing SVD XML file\n\nCaused by:\n{}", indent_chain(&e.text())),
            );
            std::process::exit(1);
        }
    };

    log(Level::Info, "svd2rust", "Rendering device");
    let rendered = match crate::gen::generate(&config.config, &device, &config.config.settings) {
        Ok(r) => r,
        Err(e) => {
            log(
                Level::Error,
                "svd2rust",
                &format!("Error rendering device\n\nCaused by:\n{}", indent_chain(&e.text())),
            );
            std::process::exit(1);
        }
    };

    // --- write output -----------------------------------------------------
    let out_dir = config.config.output_dir.clone().unwrap_or_default();
    let path = |name: &str| -> std::path::PathBuf {
        if out_dir.is_empty() {
            std::path::PathBuf::from(name)
        } else {
            std::path::PathBuf::from(&out_dir).join(name)
        }
    };
    let file_name = if config.config.make_mod {
        "mod.rs"
    } else {
        "lib.rs"
    };
    write_file(&path(file_name), &rendered.lib);
    if let Some(g) = &rendered.generic {
        write_file(&path("generic.rs"), g);
    }
    if config.config.target != crate::cfg::Target::Mips
        && config.config.target != crate::cfg::Target::None
    {
        write_file(&path("build.rs"), crate::gen::BUILD_RS);
        write_file(&path("device.x"), &rendered.device_x);
    }
    if let Some(f) = &rendered.features {
        write_file(&path("features.toml"), f);
    }
}

fn log_plain(msg: &str) {
    let formatted = format!("[ERROR svd2rust] {}", crate::log::indent(msg));
    eprintln!("{}", formatted);
}

fn indent_chain(text: &str) -> String {
    let mut out = String::new();
    for (i, line) in text.split('\n').enumerate() {
        if i > 0 {
            out.push('\n');
            out.push_str("    ");
        }
        out.push_str(line);
    }
    out
}

fn write_file(p: &std::path::Path, content: &str) {
    let f = std::fs::File::create(p);
    match f {
        Ok(mut f) => {
            use std::io::Write;
            if let Err(e) = f.write_all(content.as_bytes()) {
                panic!("Couldn't write output file: {:?}", e);
            }
        }
        Err(e) => panic!("Couldn't create output file: {:?}", e),
    }
}
RS
echo ok"}

