// Command line parsing, mimicking clap 4 behaviour.

use crate::cfg::{Config, Edition, SourceType, Target};
use crate::ident::{Case, IdentFormat, IDENT_TYPES};
use crate::util::jaro_winkler;

pub enum CliOut {
    Out(String),
    Err(String),
}

pub struct CliConfig {
    pub config: Config,
    pub base_address_shift_cli: Option<String>,
    pub config_path: Option<String>,
    pub settings_path: Option<String>,
    pub edition_cli: Option<String>,
    pub target_cli: Option<String>,
    pub source_type_cli: Option<String>,
    pub theme_cli: Option<String>,
    pub ident_formats_cli: Vec<String>,
}

struct Spec {
    short: Option<char>,
    kebab: &'static str,
    snake: &'static str,
    value: Option<&'static str>,
    possible: Option<&'static [&'static str]>,
}

const LOG_LEVELS: [&str; 6] = ["off", "error", "warn", "info", "debug", "trace"];

fn specs() -> Vec<Spec> {
    let s = |short: Option<char>,
             kebab: &'static str,
             snake: &'static str,
             value: Option<&'static str>,
             possible: Option<&'static [&'static str]>| {
        Spec {
            short,
            kebab,
            snake,
            value,
            possible,
        }
    };
    vec![
        s(Some('i'), "input", "input", Some("FILE"), None),
        s(Some('o'), "output-dir", "output_dir", Some("PATH"), None),
        s(Some('c'), "config", "config", Some("TOML_FILE"), None),
        s(None, "settings", "settings", Some("YAML_FILE"), None),
        s(None, "edition", "edition", Some("YEAR"), None),
        s(None, "target", "target", Some("ARCH"), None),
        s(None, "atomics", "atomics", None, None),
        s(None, "atomics-feature", "atomics_feature", Some("FEATURE"), None),
        s(None, "ignore-groups", "ignore_groups", None, None),
        s(None, "keep-list", "keep_list", None, None),
        s(Some('g'), "generic-mod", "generic_mod", None, None),
        s(None, "feature-group", "feature_group", None, None),
        s(None, "feature-peripheral", "feature_peripheral", None, None),
        s(
            Some('f'),
            "ident-format",
            "ident_format",
            Some("ident_format"),
            None,
        ),
        s(
            None,
            "ident-formats-theme",
            "ident_formats_theme",
            Some("THEME"),
            None,
        ),
        s(
            None,
            "field-names-for-enums",
            "field_names_for_enums",
            None,
            None,
        ),
        s(None, "max-cluster-size", "max_cluster_size", None, None),
        s(None, "impl-debug", "impl_debug", None, None),
        s(None, "impl-debug-feature", "impl_debug_feature", Some("FEATURE"), None),
        s(None, "impl-defmt", "impl_defmt", Some("FEATURE"), None),
        s(Some('m'), "make-mod", "make_mod", None, None),
        s(None, "skip-crate-attributes", "skip_crate_attributes", None, None),
        s(Some('s'), "strict", "strict", None, None),
        s(None, "source-type", "source_type", Some("source_type"), None),
        s(None, "reexport-core-peripherals", "reexport_core_peripherals", None, None),
        s(None, "reexport-interrupt", "reexport_interrupt", None, None),
        s(
            Some('b'),
            "base-address-shift",
            "base_address_shift",
            Some("base_address_shift"),
            None,
        ),
        s(Some('l'), "log", "log", Some("log_level"), Some(&LOG_LEVELS)),
    ]
}

fn usage_full() -> &'static str {
    "Usage: executable [OPTIONS]"
}

fn help_long() -> &'static str {
    crate::help_text::HELP_LONG
}

fn help_short() -> &'static str {
    crate::help_text::HELP_SHORT
}

fn version_text() -> &'static str {
    "svd2rust 0.37.1 (63c65c2 2026-06-11)\n"
}

fn err_tail() -> &'static str {
    "\nFor more information, try '--help'.\n"
}

fn value_error(spec: &Spec, value: &str) -> String {
    let name = format!("--{} <{}>", spec.kebab, spec.value.unwrap_or(""));
    let mut out = format!("error: invalid value '{}' for '{}'\n", value, name);
    if let Some(p) = spec.possible {
        out.push_str(&format!("  [possible values: {}]\n", p.join(", ")));
    }
    out.push_str(err_tail());
    out
}

fn missing_value(spec: &Spec, long: bool) -> String {
    let name = if long {
        format!("--{} <{}>", spec.kebab, spec.value.unwrap_or(""))
    } else {
        format!("-{} <{}>", spec.short.unwrap(), spec.value.unwrap_or(""))
    };
    let mut out = format!(
        "error: a value is required for '{}' but none was supplied\n",
        name
    );
    if let Some(p) = spec.possible {
        out.push_str(&format!("  [possible values: {}]\n", p.join(", ")));
    }
    out.push_str(err_tail());
    out
}

fn unexpected_value(spec: &Spec, value: &str) -> String {
    let name = format!("--{}", spec.kebab);
    format!(
        "error: unexpected value '{}' for '{}' found; no more were expected\n\nUsage: executable {}\n{}",
        value, name, name, err_tail()
    )
}

fn unknown_arg(arg: &str) -> String {
    let mut out = format!("error: unexpected argument '{}' found\n", arg);
    if let Some(name) = arg.strip_prefix("--") {
        // find the best matching option (both kebab and snake forms)
        let mut best: Option<(f64, &Spec, bool)> = None;
        for spec in specs() {
            for (cand, is_snake) in [(spec.kebab, false), (spec.snake, true)] {
                let score = jaro_winkler(name, cand);
                if score > 0.7 {
                    let better = match &best {
                        None => true,
                        Some((b, _, _)) => score > *b,
                    };
                    if better {
                        best = Some((score, spec, is_snake));
                    }
                }
            }
        }
        if let Some((_, spec, _)) = best {
            out.push_str(&format!(
                "\n  tip: a similar argument exists: '--{}'\n",
                spec.snake
            ));
            out.push_str(&format!(
                "\nUsage: executable --{}{}\n",
                spec.kebab,
                match spec.value {
                    Some(v) => format!(" <{}>", v),
                    None => String::new(),
                }
            ));
            out.push_str(err_tail());
            return out;
        }
    }
    out.push_str(&format!("\n{}\n{}", usage_full(), err_tail()));
    out
}

fn duplicate(spec: &Spec, long: bool) -> String {
    let name = if long {
        format!("--{} <{}>", spec.kebab, spec.value.unwrap_or(""))
    } else {
        format!("-{} <{}>", spec.short.unwrap(), spec.value.unwrap_or(""))
    };
    if spec.value.is_none() {
        format!(
            "error: the argument '--{}' cannot be used multiple times\n\n{}\n{}",
            spec.kebab,
            usage_full(),
            err_tail()
        )
    } else {
        format!(
            "error: the argument '{}' cannot be used multiple times\n\n{}\n{}",
            name,
            usage_full(),
            err_tail()
        )
    }
}
RS
echo ok"}

