pub fn parse() -> Result<CliConfig, CliOut> {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let mut cfg = default_config();
    let mut out = CliConfig {
        config: cfg.clone(),
        base_address_shift_cli: None,
        config_path: None,
        settings_path: None,
        edition_cli: None,
        target_cli: None,
        source_type_cli: None,
        theme_cli: None,
        ident_formats_cli: Vec::new(),
    };
    let specs = specs();
    let mut seen: Vec<&'static str> = Vec::new();
    let mut i = 0usize;
    let mut next_is_positional = false;
    while i < args.len() {
        let a = args[i].clone();
        i += 1;
        if next_is_positional {
            return Err(CliOut::Err(unknown_arg(&a)));
        }
        if a == "--" {
            next_is_positional = true;
            continue;
        }
        if let Some(rest) = a.strip_prefix("--") {
            let (name, val) = match rest.find('=') {
                Some(p) => (rest[..p].to_string(), Some(rest[p + 1..].to_string())),
                None => (rest.to_string(), None),
            };
            let spec = specs.iter().find(|s| s.kebab == name || s.snake == name);
            let spec = match spec {
                Some(s) => s,
                None => {
                    let display = if name.is_empty() {
                        "--".to_string()
                    } else {
                        format!("--{}", name)
                    };
                    return Err(CliOut::Err(unknown_arg(&display)));
                }
            };
            if spec.kebab == "help" || spec.kebab == "version" {
                // handled below
            }
            let (kebab, snake, takes_value, possible) = (spec.kebab, spec.snake, spec.value.is_some(), spec.possible);
            let val = if !takes_value {
