            let val = if !takes_value {
                match val {
                    Some(v) => {
                        return Err(CliOut::Err(unexpected_value(spec, &v)));
                    }
                    None => None,
                }
            } else {
                match val {
                    Some(v) => Some(v),
                    None => {
                        // take the next arg as a value (unless it looks like an option)
                        if i < args.len() && !args[i].starts_with('-') {
                            let v = args[i].clone();
                            i += 1;
                            Some(v)
                        } else {
                            return Err(CliOut::Err(missing_value(spec, true)));
                        }
                    }
                }
            };
            if seen.contains(&kebab) && kebab != "ident_format" {
                return Err(CliOut::Err(duplicate(spec, true)));
            }
            seen.push(kebab);
            match kebab {
                "input" => cfg.input = val,
                "output-dir" => cfg.output_dir = val,
                "config" => out.config_path = val,
                "settings" => out.settings_path = val,
                "edition" => out.edition_cli = val,
                "target" => out.target_cli = val,
                "source-type" => out.source_type_cli = val,
                "atomics" => cfg.atomics = true,
                "atomics-feature" => cfg.atomics_feature = val,
                "ignore-groups" => cfg.ignore_groups = true,
                "keep-list" => cfg.keep_list = true,
                "generic-mod" => cfg.generic_mod = true,
                "feature-group" => cfg.feature_group = true,
                "feature-peripheral" => cfg.feature_peripheral = true,
                "ident-format" => out.ident_formats_cli.push(val.unwrap_or_default()),
                "ident-formats-theme" => out.theme_cli = val,
                "field-names-for-enums" => cfg.field_names_for_enums = true,
                "max-cluster-size" => cfg.max_cluster_size = true,
                "impl-debug" => cfg.impl_debug = true,
                "impl-debug-feature" => cfg.impl_debug_feature = val,
                "impl-defmt" => cfg.impl_defmt = val,
                "make-mod" => cfg.make_mod = true,
                "skip-crate-attributes" => cfg.skip_crate_attributes = true,
                "strict" => cfg.strict = true,
                "reexport-core-peripherals" => cfg.reexport_core_peripherals = true,
                "reexport-interrupt" => cfg.reexport_interrupt = true,
                "base-address-shift" => out.base_address_shift_cli = val,
                "log" => {
                    let v = val.unwrap();
                    if let Some(p) = possible {
                        if v.is_empty() {
                            return Err(CliOut::Err(missing_value(spec, true)));
                        }
                        if !p.contains(&v.as_str()) {
                            return Err(CliOut::Err(value_error(spec, &v)));
                        }
                    }
                    cfg.log_level = Some(v);
                }
                "help" | "version" => {}
                _ => {}
            }
            continue;
        }
        if a.len() > 1 && a.starts_with('-') {
            // short flags
            let chars: Vec<char> = a.chars().skip(1).collect();
            let mut ci = 0usize;
            while ci < chars.len() {
                let c = chars[ci];
                ci += 1;
                if c == 'h' {
                    return Err(CliOut::Out(help_short().to_string()));
                }
                if c == 'V' {
                    return Err(CliOut::Out(version_text().to_string()));
                }
                let spec = specs.iter().find(|s| s.short == Some(c));
                let spec = match spec {
                    Some(s) => s,
                    None => {
                        return Err(CliOut::Err(unknown_arg(&format!("-{}", c))));
                    }
                };
                if !spec.value.is_some() {
                    if seen.contains(&spec.kebab) {
                        return Err(CliOut::Err(duplicate(spec, false)));
                    }
                    seen.push(spec.kebab);
                    apply_short(spec.kebab, &mut cfg, &mut out, Some(String::new()));
                    continue;
                }
                // takes value
                let rest: String = chars[ci..].iter().collect();
                let val = if !rest.is_empty() {
                    if rest.starts_with('=') {
                        rest[1..].to_string()
                    } else {
                        rest
                    }
                } else if i < args.len() && !args[i].starts_with('-') {
                    let v = args[i].clone();
                    i += 1;
                    v
                } else {
                    return Err(CliOut::Err(missing_value(spec, false)));
                };
                if spec.kebab == "log" {
                    if val.is_empty() {
                        return Err(CliOut::Err(missing_value(spec, true)));
                    }
                    if !spec.possible.unwrap().contains(&val.as_str()) {
                        return Err(CliOut::Err(value_error(spec, &val)));
                    }
                }
                if seen.contains(&spec.kebab) && spec.kebab != "ident_format" {
                    return Err(CliOut::Err(duplicate(spec, false)));
                }
                seen.push(spec.kebab);
                apply_short(spec.kebab, &mut cfg, &mut out, Some(val));
                continue;
            }
            continue;
        }
        return Err(CliOut::Err(unknown_arg(&a)));
    }
    out.config = cfg;
    Ok(out)
}

fn apply_short(
    kebab: &str,
    cfg: &mut Config,
    out: &mut CliConfig,
    val: Option<String>,
) {
    match kebab {
        "input" => cfg.input = val,
        "output-dir" => cfg.output_dir = val,
        "config" => out.config_path = val,
        "settings" => out.settings_path = val,
        "edition" => out.edition_cli = val,
        "target" => out.target_cli = val,
        "source-type" => out.source_type_cli = val,
        "atomics" => cfg.atomics = true,
        "atomics-feature" => cfg.atomics_feature = val,
        "ignore-groups" => cfg.ignore_groups = true,
        "keep-list" => cfg.keep_list = true,
        "generic-mod" => cfg.generic_mod = true,
        "feature-group" => cfg.feature_group = true,
        "feature-peripheral" => cfg.feature_peripheral = true,
        "ident-format" => out.ident_formats_cli.push(val.unwrap_or_default()),
        "ident-formats-theme" => out.theme_cli = val,
        "field-names-for-enums" => cfg.field_names_for_enums = true,
        "max-cluster-size" => cfg.max_cluster_size = true,
        "impl-debug" => cfg.impl_debug = true,
        "impl-debug-feature" => cfg.impl_debug_feature = val,
        "impl-defmt" => cfg.impl_defmt = val,
        "make-mod" => cfg.make_mod = true,
        "skip-crate-attributes" => cfg.skip_crate_attributes = true,
        "strict" => cfg.strict = true,
        "reexport-core-peripherals" => cfg.reexport_core_peripherals = true,
        "reexport-interrupt" => cfg.reexport_interrupt = true,
        "base-address-shift" => out.base_address_shift_cli = val,
        "log" => cfg.log_level = val,
        _ => {}
    }
}

pub fn default_config() -> Config {
    Config {
        edition: Edition::E2021,
        target: Target::CortexM,
        atomics: false,
        atomics_feature: None,
        generic_mod: false,
        make_mod: false,
        skip_crate_attributes: false,
        ignore_groups: false,
        keep_list: false,
        strict: false,
        feature_group: false,
        feature_peripheral: false,
        max_cluster_size: false,
        impl_debug: false,
        impl_debug_feature: None,
        impl_defmt: None,
        output_dir: None,
        input: None,
        source_type: SourceType::Xml,
        log_level: None,
        interrupt_link_section: None,
        reexport_core_peripherals: false,
        reexport_interrupt: false,
        ident_formats: crate::ident::ident_formats_default()
            .into_iter()
            .map(|(k, v)| (k.to_string(), v))
            .collect(),
        ident_formats_theme: None,
        field_names_for_enums: false,
        base_address_shift: 0,
        settings_file: None,
        settings: Settings {
            html_url: None,
            crate_path: None,
            riscv_config: None,
        },
    }
}

/// Apply the command line string options that require deserialization.
/// Returns an error message when a value is invalid.
pub fn deserialize_cli(
    out: &mut CliConfig,
) -> Result<(), String> {
    if let Some(e) = &out.edition_cli {
        match Edition::parse(e) {
            Some(v) => out.config.edition = v,
            None => {
                return Err(format!(
                    "unknown variant `{}`, expected `2021` or `2024`",
                    e
                ))
            }
        }
    }
    if let Some(t) = &out.theme_cli {
        if t != "legacy" {
            return Err(format!("unknown variant `{}`, expected `legacy`", t));
        }
        out.config.ident_formats_theme = Some(t.clone());
        out.config.ident_formats = crate::ident::ident_formats_theme_legacy()
            .into_iter()
            .map(|(k, v)| (k.to_string(), v))
            .collect();
    }
    if let Some(s) = &out.source_type_cli {
        match SourceType::parse(s) {
            Some(v) => out.config.source_type = v,
            None => {
                return Err(format!(
                    "unknown variant `{}`, expected one of `xml`, `yaml`, `json`",
                    s
                ))
            }
        }
    }
    if let Some(t) = &out.target_cli {
        match Target::parse(t) {
            Some(v) => out.config.target = v,
            None => {
                return Err(format!(
                    "unknown variant `{}`, expected one of `cortex-m`, `msp430`, `riscv`, `xtensa-lx`, `mips`, `none`",
                    t
                ))
            }
        }
    }
    for spec in &out.ident_formats_cli {
        apply_ident_format(&mut out.config.ident_formats, spec);
    }
    Ok(())
}

fn apply_ident_format(list: &mut crate::cfg::IdentFormats, spec: &str) {
    let parts: Vec<&str> = spec.split(':').collect();
    if parts.len() != 4 {
        return;
    }
    let (ty, prefix, case, suffix) = (parts[0], parts[1], parts[2], parts[3]);
    if !IDENT_TYPES.contains(&ty) {
        return;
    }
    let case = match Case::parse(case) {
        Some(c) => c,
        None => return,
    };
    let fmt = IdentFormat {
        case: Some(case),
        prefix: prefix.to_string(),
        suffix: suffix.to_string(),
    };
    if let Some(pos) = list.iter().position(|(k, _)| k == ty) {
        list[pos].1 = fmt;
    } else {
        list.push((ty.to_string(), fmt));
    }
}
