}

pub fn url_error(u: &str) -> Option<String> {
    // Very small subset of the `url` crate's parsing errors.
    if u.is_empty() {
        return Some(format!("relative URL without a base: {:?}", u));
    }
    let colon = u.find(':');
    let scheme = colon.map(|i| u[..i].to_lowercase());
    match &scheme {
        Some(s) if s.chars().all(|c| c.is_ascii_alphabetic() || c == '+' || c == '-' || c == '.') && !s.is_empty() => {
        }
        _ => return Some(format!("relative URL without a base: {:?}", u)),
    }
    let rest = &u[colon.unwrap() + 1..];
    if rest.starts_with("//") {
        let host_part = rest[2..].split(['/', '?', '#']).next().unwrap_or("");
        let has_userinfo = host_part.contains('@');
        let host = host_part
            .rsplit('@')
            .next()
            .unwrap_or("")
            .split(':')
            .next()
            .unwrap_or("");
        if host.is_empty() {
            return Some(format!("empty host: {:?}", u));
        }
        if host.chars().any(|c| c.is_whitespace()) {
            return Some(format!("invalid international domain name: {:?}", u));
        }
        let _ = has_userinfo;
    }
    None
}

fn apply_settings(t: &Vec<(String, Val)>, s: &mut Settings) -> Result<(), String> {
    for (k, v) in t {
        match k.as_str() {
            "html_url" => match v {
                Val::Str(u) => {
                    if let Some(e) = url_error(u) {
                        return Err(e);
                    }
                    s.html_url = Some(u.clone());
                }
                Val::Int(i) => {
                    let u = i.to_string();
                    if let Some(e) = url_error(&u) {
                        return Err(e);
                    }
                    s.html_url = Some(u);
                }
                Val::Bool(b) => {
                    let u = b.to_string();
                    if let Some(e) = url_error(&u) {
                        return Err(e);
                    }
                    s.html_url = Some(u);
                }
                other => {
                    return Err(format!(
                        "invalid type: {}, expected a string representing an URL",
                        other.debug_val()
                    ))
                }
            },
            "crate_path" => {
                s.crate_path = Some(as_str(v)?);
            }
            "riscv_config" => {
                let t = as_table(v, "struct RiscvConfig")?;
                let mut rc = RiscvConfig { eei: None, base_isa: None };
                for (k2, v2) in t {
                    match k2.as_str() {
                        "eei" => rc.eei = Some(as_str(v2)?),
                        "base_isa" => rc.base_isa = Some(as_str(v2)?),
                        _ => {}
                    }
                }
                s.riscv_config = Some(rc);
            }
            _ => {}
        }
    }
    Ok(())
}

pub fn apply_toml(c: &mut Config, table: &Vec<(String, Val)>) -> Result<(), String> {
    for (k, v) in table {
        match k.as_str() {
