            "atomics_feature" => c.atomics_feature = Some(as_str(v)?),
            "generic_mod" => c.generic_mod = as_bool(v)?,
            "make_mod" => c.make_mod = as_bool(v)?,
            "skip_crate_attributes" => c.skip_crate_attributes = as_bool(v)?,
            "ignore_groups" => c.ignore_groups = as_bool(v)?,
            "keep_list" => c.keep_list = as_bool(v)?,
            "strict" => c.strict = as_bool(v)?,
            "feature_group" => c.feature_group = as_bool(v)?,
            "feature_peripheral" => c.feature_peripheral = as_bool(v)?,
            "max_cluster_size" => c.max_cluster_size = as_bool(v)?,
            "impl_debug" => c.impl_debug = as_bool(v)?,
            "impl_debug_feature" => c.impl_debug_feature = Some(as_str(v)?),
            "impl_defmt" => c.impl_defmt = Some(as_str(v)?),
            "output_dir" => c.output_dir = Some(as_path(v)?),
            "input" => c.input = Some(as_path(v)?),
