                                    v3,
                                    &["constant", "pascal", "snake"],
                                    "unknown variant `{}`, expected one of `constant`, `pascal`, `snake`",
                                )?;
                                fmt.case = Some(match s.as_str() {
                                    "constant" => crate::ident::Case::Constant,
                                    "pascal" => crate::ident::Case::Pascal,
                                    _ => crate::ident::Case::Snake,
                                });
                            }
                            "prefix" => fmt.prefix = as_str(v3)?,
                            "suffix" => fmt.suffix = as_str(v3)?,
                            _ => {}
                        }
                    }
                    if let Some(pos) = c.ident_formats.iter().position(|(k, _)| k == k2) {
                        c.ident_formats[pos].1 = fmt;
                    } else {
                        c.ident_formats.push((k2.clone(), fmt));
                    }
                }
            }
            "settings" => {
                let t = as_table(v, "struct Settings")?;
                let mut s = Settings {
                    html_url: None,
                    crate_path: None,
                    riscv_config: None,
                };
                apply_settings(t, &mut s)?;
                c.settings = s;
            }
            _ => {}
        }
    }
    Ok(())
}
