        )),
    }
}

fn as_u64(v: &Val) -> Result<u64, String> {
    match v {
        Val::Int(i) if *i >= 0 => Ok(*i as u64),
        Val::Int(i) => Err(format!("invalid value: integer `{}`, expected u64", i)),
        other => Err(format!(
            "invalid type: {}, expected u64",
            other.debug_val()
        )),
    }
}

fn as_enum(v: &Val, variants: &[&str], msg_fmt: &str) -> Result<String, String> {
