// Minimal YAML subset parser for the `--settings` file.

#[derive(Debug, Clone)]
pub enum Yaml {
    Scalar(String, usize, usize), // value, line, column
    Seq(Vec<Yaml>, usize, usize),
    Map(Vec<(String, Yaml)>, usize, usize),
    Null,
}

pub struct YamlError {
    pub msg: String,
}

pub fn parse(input: &str) -> Result<Yaml, YamlError> {
    let lines: Vec<&str> = input.split('\n').collect();
    let mut items: Vec<(usize, usize, String)> = Vec::new();
    for (i, l) in lines.iter().enumerate() {
        let trimmed = l.trim_end();
        let indent = trimmed.len() - trimmed.trim_start().len();
        let content = trimmed.trim_start();
        if content.is_empty() || content.starts_with('#') {
            continue;
        }
        items.push((i + 1, indent + 1, content.to_string()));
    }
    let mut i = 0usize;
    let (line, col, first) = if items.is_empty() {
        (1, 1, String::new())
    } else {
        (items[0].0, items[0].1, items[0].2.clone())
    };
    let mut map: Vec<(String, Yaml)> = Vec::new();
    let base_indent = first.find(':').map(|c| col + c).unwrap_or(col);
    while i < items.len() {
        let (l, c, content) = items[i].clone();
        if c - 1 < base_indent - 1 {
            break;
        }
        let key_end = match content.find(':') {
            Some(p) => p,
            None => return Err(YamlError { msg: format!("expected ':' at line {} column {}", l, c) }),
        };
        let key = content[..key_end].trim().to_string();
        let rest = content[key_end + 1..].trim();
        if rest.is_empty() {
            // nested block
            let mut j = i + 1;
            let mut seq: Vec<Yaml> = Vec::new();
            let mut sub: Vec<(String, Yaml)> = Vec::new();
            let mut sub_indent: Option<usize> = None;
            while j < items.len() {
                let (l2, c2, content2) = items[j].clone();
                if c2 - 1 <= c - 1 {
                    break;
                }
                if sub_indent.is_none() {
                    sub_indent = Some(c2 - 1);
                }
                if content2.starts_with("- ") || content2 == "-" {
                    let v = content2[1..].trim();
                    let col2 = c2 + content2.find('-').unwrap() + 2;
                    if v.starts_with('"') && v.len() >= 2 {
                        seq.push(Yaml::Scalar(
                            v[1..v.len() - 1].to_string(),
                            l2,
                            col2 + 1,
                        ));
                    } else {
                        seq.push(Yaml::Scalar(v.to_string(), l2, col2));
                    }
                } else {
                    let k2_end = match content2.find(':') {
                        Some(p) => p,
                        None => return Err(YamlError { msg: format!("expected ':' at line {} column {}", l2, c2) }),
                    };
                    let k2 = content2[..k2_end].trim().to_string();
                    let v2 = content2[k2_end + 1..].trim();
                    let col2 = c2 + k2_end + 2;
                    if v2.is_empty() {
                        sub.push((k2, Yaml::Null));
                    } else if v2.starts_with('"') && v2.len() >= 2 {
                        sub.push((k2, Yaml::Scalar(v2[1..v2.len() - 1].to_string(), l2, col2)));
                    } else {
                        sub.push((k2, Yaml::Scalar(v2.to_string(), l2, col2)));
                    }
                }
                j += 1;
            }
            let value = if !seq.is_empty() {
                Yaml::Seq(seq, l, c)
            } else if !sub.is_empty() {
                Yaml::Map(sub, l, c)
            } else {
                Yaml::Null
            };
            map.push((key, value));
            i = j;
        } else {
            let col_v = c + key_end + 2;
            if rest.starts_with('"') && rest.len() >= 2 {
                map.push((key, Yaml::Scalar(rest[1..rest.len() - 1].to_string(), l, col_v)));
            } else {
                map.push((key, Yaml::Scalar(rest.to_string(), l, col_v)));
            }
            i += 1;
        }
    }
    Ok(Yaml::Map(map, line, col))
}
