                    return Err(format!(
                        "crate_path: invalid type: sequence, expected a string at line {} column {}",
                        l, c
                    ))
                }
                Yaml::Map(_, l, c) => {
                    return Err(format!(
                        "crate_path: invalid type: map, expected a string at line {} column {}",
                        l, c
                    ))
                }
                Yaml::Null => {}
            },
