                                    rc.eei = Some(s2.clone())
                                }
                            }
                            "base_isa" => {
                                if let Yaml::Scalar(s2, _, _) = v2 {
                                    rc.base_isa = Some(s2.clone())
                                }
                            }
                            _ => {}
                        }
                    }
                    s.riscv_config = Some(rc);
                }
                Yaml::Scalar(sv, l, c) => {
                    return Err(format!(
                        "riscv_config: invalid type: string {:?}, expected struct RiscvConfig at line {} column {}",
                        sv, l, c
                    ))
                }
                Yaml::Seq(_, l, c) => {
                    return Err(format!(
                        "riscv_config: invalid type: sequence, expected struct RiscvConfig at line {} column {}",
                        l, c
                    ))
                }
                Yaml::Null => {}
            },
            _ => {}
        }
    }
    Ok(())
}
